1	// Package relayproof implements cross-chain message verification.
2	package relayproof
3	
4	import (
5		"container/list"
6		"errors"
7		"fmt"
8		"math"
9		"os"
10		"path/filepath"
11		"sort"
12		"strconv"
13		"sync"
14		"syscall"
15	)
16	
17	// maxProcessTime is the largest legal processing time: non-negative int64
18	// Unix milliseconds, up to the int64 ceiling.
19	const maxProcessTime = math.MaxInt64
20	
21	// Durable queue statuses. Pending and waiting are live; the rest are terminal.
22	const (
23		StatusPending    = "pending"        // accepted, not processed for the first time yet
24		StatusWaiting    = "waiting"        // processed, waiting for a trusted header at proof height
25		StatusSuccess    = "success"        // recorded locally and nonce consumed
26		StatusReplay     = "replay"         // nonce combination already consumed by another message
27		StatusExpired    = "expired"        // absolute expiry reached before delivery
28		StatusUnknownSrc = "unknown-source" // source chain was never registered
29	)
30	
31	// Common errors. Callers can compare with errors.Is.
32	var (
33		// ErrConflict is returned when an id is reused with different message content.
34		ErrConflict = errors.New("message id conflict: existing record has different content")
35		// ErrHeaderConflict is returned when a trusted header is submitted at the
36		// height of the accepted highest trusted header with a different root. The
37		// accepted trusted header is kept and the queue remains usable.
38		ErrHeaderConflict = errors.New("trusted header conflict: different root at the accepted height")
39		// ErrTerminal is returned when re-submitting a terminal id or attempting to
40		// reactivate it.
41		ErrTerminal = errors.New("message is terminal and cannot be reactivated")
42		// ErrInvalidArg is returned for malformed input (empty id, bad times, ...).
43		ErrInvalidArg = errors.New("invalid argument")
44		// ErrLocked is returned when another process holds the state directory open.
45		ErrLocked = errors.New("state directory is locked by another process")
46		// ErrCorrupt is returned when on-disk state is unreadable or unsupported.
47		ErrCorrupt = errors.New("state directory is corrupt or uses an unsupported format")
48		// ErrStorage is returned after a storage failure; the queue must be reopened.
49		ErrStorage = errors.New("storage failure; queue must be reopened")
50	)
51	
52	// Envelope is a submitted message together with its absolute expiry time.
53	type Envelope struct {
54		Message Message
55		// ExpiresAt is an absolute Unix-millisecond instant. Zero means never expire.
56		ExpiresAt int64
57	}
58	
59	// Record is the full persisted state of one submitted message.
60	type Record struct {
61		Msg        Envelope
62		Status     string
63		Reason     string
64		Seq        int64 // submission order, zero-based
65		Attempts   int   // number of processing attempts
66		NextRetry  int64 // 0 when not yet processed, or terminal
67		LastProcAt int64 // processing time of the most recent attempt
68	}
69	
70	// Query is the user-visible view of a Record.
71	type Query struct {
72		ID        string
73		From      string
74		To        string
75		Nonce     uint64
76		Payload   string
77		ProofAt   int64
78		ExpiresAt int64
79		Status    string
80		Reason    string
81		NextRetry int64 // 0 = no retry scheduled (not yet processed, or terminal)
82		Attempts  int
83	}
84	
85	// AdvanceReport is the outcome of one Advance call.
86	type AdvanceReport struct {
87		Now     int64
88		Results []Result
89	}
90	
91	// Result describes what happened to one message during an Advance.
92	type Result struct {
93		ID     string `json:"id"`
94		Status string `json:"status"`
95		Reason string `json:"reason"`
96	}
97	
98	// Queue is a durable local outbox backed by a state directory. A single
99	// Queue owns the directory for writes; other processes attempting to Open the
100	// same directory fail with ErrLocked. It is safe for concurrent use by
101	// multiple goroutines, and a success record plus its nonce consumption commit
102	// as one durable unit.
103	type Queue struct {
104		mu sync.Mutex
105	
106		store  *store
107		flock  *os.File
108		broken bool // a storage write failed; all further mutations fail
109	
110		now      int64                   // last advanced Unix-ms time, 0 = never advanced
111		sources  map[string]bool         // registered source chains
112		headers  map[string]*headerState // per-chain recorded headers (latest + highest trusted)
113		records  map[string]*Record      // by message id
114		order    *pendingOrder           // non-terminal messages, first-submission order
115		consumed map[consumeToken]string // (source, destination, nonce) -> successful message id
116		nextSeq  int64
117	}
118	
119	// pendingOrder is the set of non-terminal (live) messages kept in strict
120	// first-submission order. It is an intrusive doubly-linked list indexed by
121	// message id: a message leaving the order when it terminalizes unlinks itself
122	// in constant time, instead of a linear slice scan followed by shifting every
123	// later entry. The total order-maintenance work of one advance therefore grows
124	// only with the number of non-terminal messages present when the advance
125	// began — traversed a constant number of times — never with the number of
126	// terminal results already accumulated in history. Traversal is stable under
127	// unlinking the current node, so terminalizing during a sweep neither visits a
128	// dead node nor reorders the survivors.
129	type pendingOrder struct {
130		l     *list.List               // each element's Value is the live message id
131		index map[string]*list.Element // live id -> its node
132	}
133	
134	func newPendingOrder(hint int) *pendingOrder {
135		return &pendingOrder{
136			l:     list.New(),
137			index: make(map[string]*list.Element, hint),
138		}
139	}
140	
141	// pushBack appends a newly submitted live message after every earlier one.
142	func (p *pendingOrder) pushBack(id string) {
143		if _, ok := p.index[id]; ok {
144			return
145		}
146		p.index[id] = p.l.PushBack(id)
147	}
148	
149	// remove unlinks a terminalized message in constant time. Removing an id that
150	// is no longer live is a no-op.
151	func (p *pendingOrder) remove(id string) {
152		if el, ok := p.index[id]; ok {
153			p.l.Remove(el)
154			delete(p.index, id)
155		}
156	}
157	
158	func (p *pendingOrder) len() int { return p.l.Len() }
159	
160	// ids returns the live ids in first-submission order. It is used by the
161	// in-package tests; hot paths traverse the nodes directly instead.
162	func (p *pendingOrder) ids() []string {
163		out := make([]string, 0, p.l.Len())
164		for el := p.l.Front(); el != nil; el = el.Next() {
165			out = append(out, el.Value.(string))
166		}
167		return out
168	}
169	
170	// Open opens (creating if needed) a persistent queue backed by stateDir. It
171	// takes an exclusive process lock on the directory and refuses to start when
172	// the on-disk state is corrupt or in an unsupported format, never clearing it.
173	func Open(stateDir string) (*Queue, error) {
174		if stateDir == "" {
175			return nil, fmt.Errorf("%w: empty state directory", ErrInvalidArg)
176		}
177		if err := os.MkdirAll(stateDir, 0o755); err != nil {
178			return nil, fmt.Errorf("create state directory: %w", err)
179		}
180		abs, err := filepath.Abs(stateDir)
181		if err != nil {
182			return nil, fmt.Errorf("resolve state directory: %w", err)
183		}
184	
185		lockPath := filepath.Join(abs, "lock")
186		lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
187		if err != nil {
188			return nil, fmt.Errorf("open lock file: %w", err)
189		}
190		if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
191			lock.Close()
192			return nil, fmt.Errorf("%w: %v", ErrLocked, err)
193		}
194	
195		st, state, err := openStore(abs)
196		if err != nil {
197			syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
198			lock.Close()
199			return nil, err
200		}
201	
202		q := &Queue{
203			store:    st,
204			flock:    lock,
205			sources:  state.sources,
206			headers:  state.headers,
207			records:  state.records,
208			consumed: state.consumed,
209			now:      state.now,
210			nextSeq:  state.nextSeq,
211			order:    newPendingOrder(len(state.records)),
212		}
213		q.reconstructOrder()
214		st.snap = q.snapshot
215		return q, nil
216	}
217	
218	// reconstructOrder fills the empty live order with the non-terminal records in
219	// submission (seq) order. It runs once, when opening a state directory: the
220	// per-advance cost of maintaining the order never depends on how many terminal
221	// records history has accumulated.
222	func (q *Queue) reconstructOrder() {
223		seqs := make([]int64, 0, len(q.records))
224		live := map[int64]string{}
225		for id, rec := range q.records {
226			if isTerminal(rec.Status) {
227				continue
228			}
229			seqs = append(seqs, rec.Seq)
230			live[rec.Seq] = id
231		}
232		sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
233		for _, seq := range seqs {
234			q.order.pushBack(live[seq])
235		}
236	}
237	
238	// snapshot returns a detached copy of live state for log compaction. Callers
239	// must hold mu.
240	func (q *Queue) snapshot() *loadedState {
241		s := &loadedState{
242			sources:  map[string]bool{},
243			headers:  map[string]*headerState{},
244			records:  map[string]*Record{},
245			consumed: map[consumeToken]string{},
246			now:      q.now,
247			nextSeq:  q.nextSeq,
248		}
249		for c := range q.sources {
250			s.sources[c] = true
251		}
252		for c, h := range q.headers {
253			cp := &headerState{latest: h.latest}
254			if h.trusted != nil {
255				t := *h.trusted
256				cp.trusted = &t
257			}
258			s.headers[c] = cp
259		}
260		for id, rec := range q.records {
261			cp := *rec
262			s.records[id] = &cp
263		}
264		for k, v := range q.consumed {
265			s.consumed[k] = v
266		}
267		return s
268	}
269	
270	// Close flushes, releases the directory lock and closes the queue.
271	func (q *Queue) Close() error {
272		q.mu.Lock()
273		defer q.mu.Unlock()
274		if q.flock == nil {
275			return nil
276		}
277		var err error
278		if !q.broken {
279			err = q.store.close()
280		} else {
281			q.store.forceClose()
282		}
283		syscall.Flock(int(q.flock.Fd()), syscall.LOCK_UN)
284		q.flock.Close()
285		q.flock = nil
286		return err
287	}
288	
289	// fail locks in a storage failure: the log tail may be partially written, so
290	// no further appends are allowed in this process (another append would turn a
291	// truncatable torn tail into unrecoverable corruption).
292	func (q *Queue) fail(op string, err error) error {
293		q.broken = true
294		return fmt.Errorf("%w: %s: %v", ErrStorage, op, err)
295	}
296	
297	func (q *Queue) checkWritable() error {
298		if q.flock == nil {
299			return fmt.Errorf("%w: queue is closed", ErrStorage)
300		}
301		if q.broken {
302			return fmt.Errorf("%w: a previous write failed; reopen the queue", ErrStorage)
303		}
304		return nil
305	}
306	
307	// RegisterSource records that messages may originate from chain. Idempotent.
308	func (q *Queue) RegisterSource(chain string) error {
309		if chain == "" {
310			return fmt.Errorf("%w: empty source chain", ErrInvalidArg)
311		}
312		q.mu.Lock()
313		defer q.mu.Unlock()
314		if err := q.checkWritable(); err != nil {
315			return err
316		}
317		if q.sources[chain] {
318			return nil
319		}
320		if err := q.store.appendRegisterSource(chain); err != nil {
321			return q.fail("register source", err)
322		}
323		q.sources[chain] = true
324		return q.maybeCompact()
325	}
326	
327	// UpsertHeader records a header for a chain. The latest header is always
328	// recorded, but proof coverage is determined solely by the highest trusted
329	// header accepted for the chain:
330	//
331	//   - the first trusted header establishes coverage;
332	//   - a higher trusted header advances it;
333	//   - a lower trusted header, or an untrusted header of any height, is
334	//     recorded but can never lower or invalidate established coverage;
335	//   - a trusted header at the current highest trusted height with the same
336	//     root is an idempotent no-op;
337	//   - a trusted header at that height with a different root is an
338	//     ErrHeaderConflict: the accepted trusted header is kept and the queue
339	//     remains usable.
340	//
341	// These update rules are the shared ones in headerState.planUpdate, with
342	// submitSameHeight as the same-height acceptance rule; log replay of the
343	// saved header applies the same rules with the recovery policy instead.
344	//
345	// Header updates never bypass retry scheduling, never process messages, and
346	// never reactivate terminal messages.
347	func (q *Queue) UpsertHeader(h Header) error {
348		if h.Chain == "" {
349			return fmt.Errorf("%w: empty header chain", ErrInvalidArg)
350		}
351		if h.Height < 0 {
352			return fmt.Errorf("%w: negative header height", ErrInvalidArg)
353		}
354		q.mu.Lock()
355		defer q.mu.Unlock()
356		if err := q.checkWritable(); err != nil {
357			return err
358		}
359		hs := q.headers[h.Chain]
360		if hs == nil {
361			hs = &headerState{}
362			q.headers[h.Chain] = hs
363		}
364		// Judge before persisting: a rejected header (a same-height conflict)
365		// touches neither the log nor the recorded state.
366		update, err := hs.planUpdate(h, submitSameHeight)
367		if err != nil {
368			return err
369		}
370		if err := q.store.appendHeader(h); err != nil {
371			return q.fail("upsert header", err)
372		}
373		hs.applyUpdate(h, update)
374		return q.maybeCompact()
375	}
376	
377	// Submit enqueues a message with an absolute expiry (Unix milliseconds; zero
378	// means never expire). Re-submitting the same id with identical content
379	// returns the existing record without adding a queue entry; the same id with
380	// different content returns ErrConflict and leaves the original untouched;
381	// re-submitting a terminal id returns ErrTerminal. Success is reported only
382	// after the submission is durably persisted.
383	func (q *Queue) Submit(env Envelope) (*Record, error) {
384		m := env.Message
385		if m.ID == "" {
386			return nil, fmt.Errorf("%w: empty message id", ErrInvalidArg)
387		}
388		if m.From == "" || m.To == "" {
389			return nil, fmt.Errorf("%w: empty source or destination chain", ErrInvalidArg)
390		}
391		if m.ProofAt < 0 {
392			return nil, fmt.Errorf("%w: negative proof height", ErrInvalidArg)
393		}
394		if env.ExpiresAt < 0 {
395			return nil, fmt.Errorf("%w: negative expiry time", ErrInvalidArg)
396		}
397	
398		q.mu.Lock()
399		defer q.mu.Unlock()
400		if err := q.checkWritable(); err != nil {
401			return nil, err
402		}
403	
404		if existing, ok := q.records[m.ID]; ok {
405			if isTerminal(existing.Status) {
406				return nil, fmt.Errorf("%w: message %s is %s", ErrTerminal, m.ID, existing.Status)
407			}
408			if sameEnvelope(existing.Msg, env) {
409				out := *existing
410				return &out, nil
411			}
412			return nil, fmt.Errorf("%w: message %s", ErrConflict, m.ID)
413		}
414	
415		rec := &Record{
416			Msg:    env,
417			Status: StatusPending,
418			Reason: "awaiting first processing",
419			Seq:    q.nextSeq,
420		}
421		if err := q.store.appendSubmit(rec); err != nil {
422			return nil, q.fail("submit", err)
423		}
424		q.records[m.ID] = rec
425		q.order.pushBack(m.ID)
426		q.nextSeq++
427		if err := q.maybeCompact(); err != nil {
428			return nil, err
429		}
430		out := *rec
431		return &out, nil
432	}
433	
434	// Advance moves processing time to nowMs (Unix milliseconds). Equal time may
435	// be advanced repeatedly; going backwards is rejected and changes nothing.
436	//
437	// Each advance, in submission order:
438	//  1. due messages (new messages are due on the next advance; others when now
439	//     has reached their next retry time) are evaluated for replay and expiry,
440	//     replay winning on a tie and now == ExpiresAt counting as expired, then
441	//     for source registration and trusted-header coverage, and finally
442	//     delivered;
443	//  2. afterwards every remaining non-terminal message, regardless of its
444	//     retry schedule, is re-checked for replay and expiry at the new time.
445	//
446	// Unregistered sources are permanently rejected as unknown-source; registered
447	// sources without a trusted header covering the proof height stay waiting and
448	// do not consume the nonce. Waiting retry intervals are 1,2,4,... seconds,
449	// doubling to a 60-second cap, measured from the actual processing time;
450	// jumping over several intervals still costs one attempt.
451	//
452	// The retry instant saturates at the int64 ceiling: a waiting message whose
453	// computed retry would overflow is scheduled for math.MaxInt64 instead, never
454	// a negative, zero or earlier-than-processing instant. Once such a message has
455	// been processed at the ceiling, every later advance is at the same instant,
456	// so it is never due again and keeps its waiting status, reason, attempt
457	// count and ceiling retry time; it is neither reprocessed nor reported again
458	// as a waiting result. Replay and expiry checks, which run independently of
459	// the retry schedule, still apply to it, and a header update alone never
460	// delivers it.
461	func (q *Queue) Advance(nowMs int64) (*AdvanceReport, error) {
462		if nowMs < 0 {
463			return nil, fmt.Errorf("%w: negative processing time", ErrInvalidArg)
464		}
465		q.mu.Lock()
466		defer q.mu.Unlock()
467		if err := q.checkWritable(); err != nil {
468			return nil, err
469		}
470		if q.now != 0 && nowMs < q.now {
471			return nil, fmt.Errorf("%w: processing time %d precedes last advanced time %d", ErrInvalidArg, nowMs, q.now)
472		}
473	
474		report := &AdvanceReport{Now: nowMs}
475	
476		// Phase 1: due messages, first-submission order. Traversal walks the live
477		// list directly and captures the successor before processing, because a
478		// result that terminalizes — and therefore unlinks — the current node
479		// leaves that node without a successor afterwards. Doing so neither
480		// corrupts the walk nor changes any survivor's position. Each unlink is
481		// constant-time, so maintaining the order across the whole phase costs
482		// only one pass over the live messages.
483		el := q.order.l.Front()
484		for el != nil {
485			id := el.Value.(string)
486			el = el.Next()
487			rec := q.records[id]
488			if rec == nil || isTerminal(rec.Status) {
489				continue
490			}
491			due := rec.Attempts == 0 || retryDue(rec, nowMs)
492			if !due {
493				continue
494			}
495			if r, done, err := q.checkReplayExpiry(rec, nowMs); err != nil {
496				return nil, err
497			} else if done {
498				report.Results = append(report.Results, r)
499				continue
500			}
501			r, err := q.processDue(rec, nowMs)
502			if err != nil {
503				return nil, err
504			}
505			report.Results = append(report.Results, r)
506		}
507	
508		// Phase 2: replay/expiry hold for every non-terminal message at the new
509		// time, even while its retry backoff is still running. Messages that
510		// terminalized in phase 1 are already gone from the list, so this sweep
511		// (plus every constant-time unlink it triggers) again costs one linear
512		// pass over the remaining live messages only — never over history.
513		el = q.order.l.Front()
514		for el != nil {
515			id := el.Value.(string)
516			// Capture the successor before processing: checkReplayExpiry may
517			// terminalize — and unlink — this very node.
518			el = el.Next()
519			rec := q.records[id]
520			if rec == nil || isTerminal(rec.Status) {
521				continue
522			}
523			if r, done, err := q.checkReplayExpiry(rec, nowMs); err != nil {
524				return nil, err
525			} else if done {
526				report.Results = append(report.Results, r)
527			}
528		}
529	
530		if err := q.store.appendAdvance(nowMs); err != nil {
531			return nil, q.fail("advance", err)
532		}
533		q.now = nowMs
534		if err := q.maybeCompact(); err != nil {
535			return nil, err
536		}
537		return report, nil
538	}
539	
540	// maybeCompact rewrites the WAL as a snapshot once it grows past the
541	// threshold. Live state already reflects every acknowledged append, so the
542	// snapshot cannot lose records. A compaction failure is a storage failure:
543	// the queue is marked broken and must be reopened.
544	func (q *Queue) maybeCompact() error {
545		if !q.store.needsCompaction() {
546			return nil
547		}
548		if err := q.store.compact(q.snapshot()); err != nil {
549			return q.fail("compact log", err)
550		}
551		return nil
552	}
553	
554	// checkReplayExpiry terminalizes rec when its nonce was consumed by another
555	// message or its absolute expiry has been reached. Replay wins when both
556	// hold. The bool reports whether the message was terminalized.
557	func (q *Queue) checkReplayExpiry(rec *Record, now int64) (Result, bool, error) {
558		id := rec.Msg.Message.ID
559		token := newConsumeToken(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
560		if winner, taken := q.consumed[token]; taken && winner != id {
561			reason := "nonce combination already consumed by message " + winner
562			r, err := q.applyOutcome(rec, now, terminalOutcome(StatusReplay, reason))
563			if err != nil {
564				return Result{}, false, err
565			}
566			return r, true, nil
567		}
568		if rec.Msg.ExpiresAt != 0 && now >= rec.Msg.ExpiresAt {
569			reason := "expired at " + strconv.FormatInt(rec.Msg.ExpiresAt, 10)
570			r, err := q.applyOutcome(rec, now, terminalOutcome(StatusExpired, reason))
571			if err != nil {
572				return Result{}, false, err
573			}
574			return r, true, nil
575		}
576		return Result{}, false, nil
577	}
578	
579	// processDue classifies a due message against source registration and header
580	// trust, or delivers it.
581	func (q *Queue) processDue(rec *Record, now int64) (Result, error) {
582		m := rec.Msg.Message
583		if !q.sources[m.From] {
584			reason := "unknown source chain " + m.From
585			return q.applyOutcome(rec, now, terminalOutcome(StatusUnknownSrc, reason))
586		}
587		hs := q.headers[m.From]
588		if hs == nil || hs.trusted == nil || hs.trusted.Height < m.ProofAt {
589			cur := int64(0)
590			if hs != nil && hs.trusted != nil {
591				cur = hs.trusted.Height
592			}
593			reason := fmt.Sprintf("waiting for trusted header covering height %d (current %d)", m.ProofAt, cur)
594			return q.applyOutcome(rec, now, waitingOutcome(reason))
595		}
596	
597		// Deliver: success record and nonce consumption are one log entry. The
598		// coverage height is the highest trusted header actually accepted — never
599		// a higher untrusted header.
600		token := newConsumeToken(m.From, m.To, m.Nonce)
601		reason := "delivered; proof verified by trusted header at height " + strconv.FormatInt(hs.trusted.Height, 10)
602		return q.applyOutcome(rec, now, successOutcome(reason, token))
603	}
604	
605	// outcome describes one processing result independently of which path found
606	// it: waiting for header coverage, delivery, or one of the terminal rejections
607	// (replay, expiry, unknown source). It carries only the business differences
608	// between the result kinds; the rules shared by every result — one more
609	// attempt, the processing-time stamp, how the result is persisted and when the
610	// record may change — live solely in applyOutcome.
611	type outcome struct {
612		status string
613		reason string
614		// consume is set only for success: the message's own
615		// (source, destination, nonce) triple, attributed to that message. No
616		// other result kind consumes a nonce.
617		consume *consumeToken
618		// op labels the failing operation in the storage error for this kind of
619		// result, keeping each path's historical error wording.
620		op string
621	}
622	
623	// waitingOutcome keeps the message live with its status unchanged in kind and
624	// its existing backoff machinery: the actual retry instant is computed by
625	// applyOutcome from the processing time and the new attempt number.
626	func waitingOutcome(reason string) outcome {
627		return outcome{status: StatusWaiting, reason: reason, op: "schedule retry"}
628	}
629	
630	// terminalOutcome settles a non-success result that ends processing: replay,
631	// expiry or unknown-source. Such results clear the retry schedule, consume no
632	// nonce and leave the live processing order.
633	func terminalOutcome(status, reason string) outcome {
634		return outcome{status: status, reason: reason, op: "terminalize"}
635	}
636	
637	// successOutcome delivers the message: it clears the retry schedule, leaves
638	// the processing order and records consumption of the message's own triple,
639	// attributed to the message itself, in the same durable record as the success
640	// state.
641	func successOutcome(reason string, token consumeToken) outcome {
642		return outcome{status: StatusSuccess, reason: reason, consume: &token, op: "deliver"}
643	}
644	
645	// applyOutcome is the single path through which every processing result is
646	// saved and takes effect. It persists the result first and touches the record
647	// only after the save is acknowledged, so a failed write changes nothing: the
648	// message keeps its previous status, reason, attempt count, processing time
649	// and retry schedule, its nonce is not consumed, and earlier results already
650	// acknowledged in the same advance stay in force. On success every result
651	// counts exactly one more attempt and stamps LastProcAt with the processing
652	// time; a waiting result additionally keeps its saturated backoff schedule,
653	// while success and terminal results clear the retry time and leave the
654	// processing order; success also records the nonce consumption.
655	func (q *Queue) applyOutcome(rec *Record, now int64, oc outcome) (Result, error) {
656		id := rec.Msg.Message.ID
657		attempt := rec.Attempts + 1
658		nextRetry := int64(0)
659		if oc.status == StatusWaiting {
660			nextRetry = nextRetryAt(now, attempt)
661		}
662		if err := q.store.appendOutcome(now, rec, attempt, nextRetry, oc); err != nil {
663			return Result{}, q.fail(oc.op, err)
664		}
665		rec.Attempts = attempt
666		rec.LastProcAt = now
667		rec.Status = oc.status
668		rec.Reason = oc.reason
669		rec.NextRetry = nextRetry
670		if oc.consume != nil {
671			q.consumed[*oc.consume] = id
672		}
673		if isTerminal(oc.status) {
674			q.order.remove(id)
675		}
676		return Result{ID: id, Status: oc.status, Reason: oc.reason}, nil
677	}
678	
679	// retryDue reports whether a waiting record's next retry is reached at now.
680	// Backoff delays are always positive, so every representable retry lies
681	// strictly after the processing time that scheduled it; a waiting message is
682	// therefore evaluated at most once per distinct processing time. The only
683	// instant where the retry cannot lie later is the int64 ceiling: there the
684	// schedule saturates to the ceiling itself. Once the message was processed at
685	// the ceiling, every legal advance is at the same instant, so the retry can
686	// never be reached "later" — treating equal time as due would reprocess the
687	// message on every advance, inflate attempts and re-report waiting forever.
688	func retryDue(rec *Record, now int64) bool {
689		if now < rec.NextRetry {
690			return false
691		}
692		return now != rec.LastProcAt
693	}
694	
695	// nextRetryAt returns the retry instant after the attempt-th processing at
696	// now: now plus the backoff delay, saturated at math.MaxInt64. Saturation
697	// keeps the scheduled retry non-negative, never zero (when processed at a
698	// positive time) and never earlier than the processing time; when the true
699	// retry overflows int64 the ceiling is the nearest representable instant.
700	func nextRetryAt(now int64, attempt int) int64 {
701		delay := nextRetryDelay(attempt)
702		if now > maxProcessTime-delay {
703			return maxProcessTime // now+delay would overflow; delay is at most 60000
704		}
705		return now + delay
706	}
707	
708	// nextRetryDelay is the backoff after the attempt-th processing (1-based):
709	// 1s, 2s, 4s, 8s, 16s, 32s, then 60s capped, in milliseconds.
710	func nextRetryDelay(attempt int) int64 {
711		if attempt < 1 {
712			attempt = 1
713		}
714		if attempt > 6 {
715			return 60_000
716		}
717		return int64(1) << (attempt - 1) * 1000
718	}
719	
720	func isTerminal(status string) bool {
721		switch status {
722		case StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
723			return true
724		}
725		return false
726	}
727	
728	func sameEnvelope(a, b Envelope) bool {
729		return a.ExpiresAt == b.ExpiresAt &&
730			a.Message.ID == b.Message.ID &&
731			a.Message.From == b.Message.From &&
732			a.Message.To == b.Message.To &&
733			a.Message.Nonce == b.Message.Nonce &&
734			a.Message.Payload == b.Message.Payload &&
735			a.Message.ProofAt == b.Message.ProofAt
736	}
737	
738	// Query returns the current state of a message.
739	func (q *Queue) Query(id string) (Query, bool) {
740		q.mu.Lock()
741		defer q.mu.Unlock()
742		rec, ok := q.records[id]
743		if !ok {
744			return Query{}, false
745		}
746		return toQuery(rec), true
747	}
748	
749	// Queries returns all records in first-submission order.
750	func (q *Queue) Queries() []Query {
751		q.mu.Lock()
752		defer q.mu.Unlock()
753		out := make([]Query, 0, len(q.records))
754		for _, rec := range q.records {
755			out = append(out, toQuery(rec))
756		}
757		sort.Slice(out, func(i, j int) bool {
758			return q.records[out[i].ID].Seq < q.records[out[j].ID].Seq
759		})
760		return out
761	}
762	
763	// Now returns the last advanced processing time, or 0 if never advanced.
764	func (q *Queue) Now() int64 {
765		q.mu.Lock()
766		defer q.mu.Unlock()
767		return q.now
768	}
769	
770	func toQuery(rec *Record) Query {
771		return Query{
772			ID:        rec.Msg.Message.ID,
773			From:      rec.Msg.Message.From,
774			To:        rec.Msg.Message.To,
775			Nonce:     rec.Msg.Message.Nonce,
776			Payload:   rec.Msg.Message.Payload,
777			ProofAt:   rec.Msg.Message.ProofAt,
778			ExpiresAt: rec.Msg.ExpiresAt,
779			Status:    rec.Status,
780			Reason:    rec.Reason,
781			NextRetry: rec.NextRetry,
782			Attempts:  rec.Attempts,
783		}
784	}
785

