// Package relayproof implements cross-chain message verification.
package relayproof

import (
	"container/list"
	"errors"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"sync"
	"syscall"
)

// maxProcessTime is the largest legal processing time: non-negative int64
// Unix milliseconds, up to the int64 ceiling.
const maxProcessTime = math.MaxInt64

// Durable queue statuses. Pending and waiting are live; the rest are terminal.
const (
	StatusPending    = "pending"        // accepted, not processed for the first time yet
	StatusWaiting    = "waiting"        // processed, waiting for a trusted header at proof height
	StatusSuccess    = "success"        // recorded locally and nonce consumed
	StatusReplay     = "replay"         // nonce combination already consumed by another message
	StatusExpired    = "expired"        // absolute expiry reached before delivery
	StatusUnknownSrc = "unknown-source" // source chain was never registered
)

// Common errors. Callers can compare with errors.Is.
var (
	// ErrConflict is returned when an id is reused with different message content.
	ErrConflict = errors.New("message id conflict: existing record has different content")
	// ErrHeaderConflict is returned when a trusted header is submitted at the
	// height of the accepted highest trusted header with a different root. The
	// accepted trusted header is kept and the queue remains usable.
	ErrHeaderConflict = errors.New("trusted header conflict: different root at the accepted height")
	// ErrTerminal is returned when re-submitting a terminal id or attempting to
	// reactivate it.
	ErrTerminal = errors.New("message is terminal and cannot be reactivated")
	// ErrInvalidArg is returned for malformed input (empty id, bad times, ...).
	ErrInvalidArg = errors.New("invalid argument")
	// ErrLocked is returned when another process holds the state directory open.
	ErrLocked = errors.New("state directory is locked by another process")
	// ErrCorrupt is returned when on-disk state is unreadable or unsupported.
	ErrCorrupt = errors.New("state directory is corrupt or uses an unsupported format")
	// ErrStorage is returned after a storage failure; the queue must be reopened.
	ErrStorage = errors.New("storage failure; queue must be reopened")
)

// Envelope is a submitted message together with its absolute expiry time.
type Envelope struct {
	Message Message
	// ExpiresAt is an absolute Unix-millisecond instant. Zero means never expire.
	ExpiresAt int64
}

// Record is the full persisted state of one submitted message.
type Record struct {
	Msg        Envelope
	Status     string
	Reason     string
	Seq        int64 // submission order, zero-based
	Attempts   int   // number of processing attempts
	NextRetry  int64 // 0 when not yet processed, or terminal
	LastProcAt int64 // processing time of the most recent attempt
}

// Query is the user-visible view of a Record.
type Query struct {
	ID        string
	From      string
	To        string
	Nonce     uint64
	Payload   string
	ProofAt   int64
	ExpiresAt int64
	Status    string
	Reason    string
	NextRetry int64 // 0 = no retry scheduled (not yet processed, or terminal)
	Attempts  int
}

// AdvanceReport is the outcome of one Advance call.
type AdvanceReport struct {
	Now     int64
	Results []Result
}

// Result describes what happened to one message during an Advance.
type Result struct {
	ID     string `json:"id"`
	Status string `json:"status"`
	Reason string `json:"reason"`
}

// Queue is a durable local outbox backed by a state directory. A single
// Queue owns the directory for writes; other processes attempting to Open the
// same directory fail with ErrLocked. It is safe for concurrent use by
// multiple goroutines, and a success record plus its nonce consumption commit
// as one durable unit.
type Queue struct {
	mu sync.Mutex

	store  *store
	flock  *os.File
	broken bool // a storage write failed; all further mutations fail

	now      int64                   // last advanced Unix-ms time, 0 = never advanced
	sources  map[string]bool         // registered source chains
	headers  map[string]*headerState // per-chain recorded headers (latest + highest trusted)
	records  map[string]*Record      // by message id
	order    *pendingOrder           // non-terminal messages, first-submission order
	consumed map[consumeToken]string // (source, destination, nonce) -> successful message id
	nextSeq  int64
}

// pendingOrder is the set of non-terminal (live) messages kept in strict
// first-submission order. It is an intrusive doubly-linked list indexed by
// message id: a message leaving the order when it terminalizes unlinks itself
// in constant time, instead of a linear slice scan followed by shifting every
// later entry. The total order-maintenance work of one advance therefore grows
// only with the number of non-terminal messages present when the advance
// began — traversed a constant number of times — never with the number of
// terminal results already accumulated in history. Traversal is stable under
// unlinking the current node, so terminalizing during a sweep neither visits a
// dead node nor reorders the survivors.
type pendingOrder struct {
	l     *list.List               // each element's Value is the live message id
	index map[string]*list.Element // live id -> its node
}

func newPendingOrder(hint int) *pendingOrder {
	return &pendingOrder{
		l:     list.New(),
		index: make(map[string]*list.Element, hint),
	}
}

// pushBack appends a newly submitted live message after every earlier one.
func (p *pendingOrder) pushBack(id string) {
	if _, ok := p.index[id]; ok {
		return
	}
	p.index[id] = p.l.PushBack(id)
}

// remove unlinks a terminalized message in constant time. Removing an id that
// is no longer live is a no-op.
func (p *pendingOrder) remove(id string) {
	if el, ok := p.index[id]; ok {
		p.l.Remove(el)
		delete(p.index, id)
	}
}

func (p *pendingOrder) len() int { return p.l.Len() }

// ids returns the live ids in first-submission order. It is used by the
// in-package tests; hot paths traverse the nodes directly instead.
func (p *pendingOrder) ids() []string {
	out := make([]string, 0, p.l.Len())
	for el := p.l.Front(); el != nil; el = el.Next() {
		out = append(out, el.Value.(string))
	}
	return out
}

// Open opens (creating if needed) a persistent queue backed by stateDir. It
// takes an exclusive process lock on the directory and refuses to start when
// the on-disk state is corrupt or in an unsupported format, never clearing it.
func Open(stateDir string) (*Queue, error) {
	if stateDir == "" {
		return nil, fmt.Errorf("%w: empty state directory", ErrInvalidArg)
	}
	if err := os.MkdirAll(stateDir, 0o755); err != nil {
		return nil, fmt.Errorf("create state directory: %w", err)
	}
	abs, err := filepath.Abs(stateDir)
	if err != nil {
		return nil, fmt.Errorf("resolve state directory: %w", err)
	}

	lockPath := filepath.Join(abs, "lock")
	lock, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		return nil, fmt.Errorf("open lock file: %w", err)
	}
	if err := syscall.Flock(int(lock.Fd()), syscall.LOCK_EX|syscall.LOCK_NB); err != nil {
		lock.Close()
		return nil, fmt.Errorf("%w: %v", ErrLocked, err)
	}

	st, state, err := openStore(abs)
	if err != nil {
		syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
		lock.Close()
		return nil, err
	}

	q := &Queue{
		store:    st,
		flock:    lock,
		sources:  state.sources,
		headers:  state.headers,
		records:  state.records,
		consumed: state.consumed,
		now:      state.now,
		nextSeq:  state.nextSeq,
		order:    newPendingOrder(len(state.records)),
	}
	q.reconstructOrder()
	st.snap = q.snapshot
	return q, nil
}

// reconstructOrder fills the empty live order with the non-terminal records in
// submission (seq) order. It runs once, when opening a state directory: the
// per-advance cost of maintaining the order never depends on how many terminal
// records history has accumulated.
func (q *Queue) reconstructOrder() {
	seqs := make([]int64, 0, len(q.records))
	live := map[int64]string{}
	for id, rec := range q.records {
		if isTerminal(rec.Status) {
			continue
		}
		seqs = append(seqs, rec.Seq)
		live[rec.Seq] = id
	}
	sort.Slice(seqs, func(i, j int) bool { return seqs[i] < seqs[j] })
	for _, seq := range seqs {
		q.order.pushBack(live[seq])
	}
}

// snapshot returns a detached copy of live state for log compaction. Callers
// must hold mu.
func (q *Queue) snapshot() *loadedState {
	s := &loadedState{
		sources:  map[string]bool{},
		headers:  map[string]*headerState{},
		records:  map[string]*Record{},
		consumed: map[consumeToken]string{},
		now:      q.now,
		nextSeq:  q.nextSeq,
	}
	for c := range q.sources {
		s.sources[c] = true
	}
	for c, h := range q.headers {
		cp := &headerState{latest: h.latest}
		if h.trusted != nil {
			t := *h.trusted
			cp.trusted = &t
		}
		s.headers[c] = cp
	}
	for id, rec := range q.records {
		cp := *rec
		s.records[id] = &cp
	}
	for k, v := range q.consumed {
		s.consumed[k] = v
	}
	return s
}

// Close flushes, releases the directory lock and closes the queue.
func (q *Queue) Close() error {
	q.mu.Lock()
	defer q.mu.Unlock()
	if q.flock == nil {
		return nil
	}
	var err error
	if !q.broken {
		err = q.store.close()
	} else {
		q.store.forceClose()
	}
	syscall.Flock(int(q.flock.Fd()), syscall.LOCK_UN)
	q.flock.Close()
	q.flock = nil
	return err
}

// fail locks in a storage failure: the log tail may be partially written, so
// no further appends are allowed in this process (another append would turn a
// truncatable torn tail into unrecoverable corruption).
func (q *Queue) fail(op string, err error) error {
	q.broken = true
	return fmt.Errorf("%w: %s: %v", ErrStorage, op, err)
}

func (q *Queue) checkWritable() error {
	if q.flock == nil {
		return fmt.Errorf("%w: queue is closed", ErrStorage)
	}
	if q.broken {
		return fmt.Errorf("%w: a previous write failed; reopen the queue", ErrStorage)
	}
	return nil
}

// RegisterSource records that messages may originate from chain. Idempotent.
func (q *Queue) RegisterSource(chain string) error {
	if chain == "" {
		return fmt.Errorf("%w: empty source chain", ErrInvalidArg)
	}
	q.mu.Lock()
	defer q.mu.Unlock()
	if err := q.checkWritable(); err != nil {
		return err
	}
	if q.sources[chain] {
		return nil
	}
	if err := q.store.appendRegisterSource(chain); err != nil {
		return q.fail("register source", err)
	}
	q.sources[chain] = true
	return q.maybeCompact()
}

// UpsertHeader records a header for a chain. The latest header is always
// recorded, but proof coverage is determined solely by the highest trusted
// header accepted for the chain:
//
//   - the first trusted header establishes coverage;
//   - a higher trusted header advances it;
//   - a lower trusted header, or an untrusted header of any height, is
//     recorded but can never lower or invalidate established coverage;
//   - a trusted header at the current highest trusted height with the same
//     root is an idempotent no-op;
//   - a trusted header at that height with a different root is an
//     ErrHeaderConflict: the accepted trusted header is kept and the queue
//     remains usable.
//
// These update rules are the shared ones in headerState.planUpdate, with
// submitSameHeight as the same-height acceptance rule; log replay of the
// saved header applies the same rules with the recovery policy instead.
//
// Header updates never bypass retry scheduling, never process messages, and
// never reactivate terminal messages.
func (q *Queue) UpsertHeader(h Header) error {
	if h.Chain == "" {
		return fmt.Errorf("%w: empty header chain", ErrInvalidArg)
	}
	if h.Height < 0 {
		return fmt.Errorf("%w: negative header height", ErrInvalidArg)
	}
	q.mu.Lock()
	defer q.mu.Unlock()
	if err := q.checkWritable(); err != nil {
		return err
	}
	hs := q.headers[h.Chain]
	if hs == nil {
		hs = &headerState{}
		q.headers[h.Chain] = hs
	}
	// Judge before persisting: a rejected header (a same-height conflict)
	// touches neither the log nor the recorded state.
	update, err := hs.planUpdate(h, submitSameHeight)
	if err != nil {
		return err
	}
	if err := q.store.appendHeader(h); err != nil {
		return q.fail("upsert header", err)
	}
	hs.applyUpdate(h, update)
	return q.maybeCompact()
}

// Submit enqueues a message with an absolute expiry (Unix milliseconds; zero
// means never expire). Re-submitting the same id with identical content
// returns the existing record without adding a queue entry; the same id with
// different content returns ErrConflict and leaves the original untouched;
// re-submitting a terminal id returns ErrTerminal. Success is reported only
// after the submission is durably persisted.
func (q *Queue) Submit(env Envelope) (*Record, error) {
	m := env.Message
	if m.ID == "" {
		return nil, fmt.Errorf("%w: empty message id", ErrInvalidArg)
	}
	if m.From == "" || m.To == "" {
		return nil, fmt.Errorf("%w: empty source or destination chain", ErrInvalidArg)
	}
	if m.ProofAt < 0 {
		return nil, fmt.Errorf("%w: negative proof height", ErrInvalidArg)
	}
	if env.ExpiresAt < 0 {
		return nil, fmt.Errorf("%w: negative expiry time", ErrInvalidArg)
	}

	q.mu.Lock()
	defer q.mu.Unlock()
	if err := q.checkWritable(); err != nil {
		return nil, err
	}

	if existing, ok := q.records[m.ID]; ok {
		if isTerminal(existing.Status) {
			return nil, fmt.Errorf("%w: message %s is %s", ErrTerminal, m.ID, existing.Status)
		}
		if sameEnvelope(existing.Msg, env) {
			out := *existing
			return &out, nil
		}
		return nil, fmt.Errorf("%w: message %s", ErrConflict, m.ID)
	}

	rec := &Record{
		Msg:    env,
		Status: StatusPending,
		Reason: "awaiting first processing",
		Seq:    q.nextSeq,
	}
	if err := q.store.appendSubmit(rec); err != nil {
		return nil, q.fail("submit", err)
	}
	q.records[m.ID] = rec
	q.order.pushBack(m.ID)
	q.nextSeq++
	if err := q.maybeCompact(); err != nil {
		return nil, err
	}
	out := *rec
	return &out, nil
}

// Advance moves processing time to nowMs (Unix milliseconds). Equal time may
// be advanced repeatedly; going backwards is rejected and changes nothing.
//
// Each advance, in submission order:
//  1. due messages (new messages are due on the next advance; others when now
//     has reached their next retry time) are evaluated for replay and expiry,
//     replay winning on a tie and now == ExpiresAt counting as expired, then
//     for source registration and trusted-header coverage, and finally
//     delivered;
//  2. afterwards every remaining non-terminal message, regardless of its
//     retry schedule, is re-checked for replay and expiry at the new time.
//
// Unregistered sources are permanently rejected as unknown-source; registered
// sources without a trusted header covering the proof height stay waiting and
// do not consume the nonce. Waiting retry intervals are 1,2,4,... seconds,
// doubling to a 60-second cap, measured from the actual processing time;
// jumping over several intervals still costs one attempt.
//
// The retry instant saturates at the int64 ceiling: a waiting message whose
// computed retry would overflow is scheduled for math.MaxInt64 instead, never
// a negative, zero or earlier-than-processing instant. Once such a message has
// been processed at the ceiling, every later advance is at the same instant,
// so it is never due again and keeps its waiting status, reason, attempt
// count and ceiling retry time; it is neither reprocessed nor reported again
// as a waiting result. Replay and expiry checks, which run independently of
// the retry schedule, still apply to it, and a header update alone never
// delivers it.
func (q *Queue) Advance(nowMs int64) (*AdvanceReport, error) {
	if nowMs < 0 {
		return nil, fmt.Errorf("%w: negative processing time", ErrInvalidArg)
	}
	q.mu.Lock()
	defer q.mu.Unlock()
	if err := q.checkWritable(); err != nil {
		return nil, err
	}
	if q.now != 0 && nowMs < q.now {
		return nil, fmt.Errorf("%w: processing time %d precedes last advanced time %d", ErrInvalidArg, nowMs, q.now)
	}

	report := &AdvanceReport{Now: nowMs}

	// Phase 1: due messages, first-submission order. Traversal walks the live
	// list directly and captures the successor before processing, because a
	// result that terminalizes — and therefore unlinks — the current node
	// leaves that node without a successor afterwards. Doing so neither
	// corrupts the walk nor changes any survivor's position. Each unlink is
	// constant-time, so maintaining the order across the whole phase costs
	// only one pass over the live messages.
	el := q.order.l.Front()
	for el != nil {
		id := el.Value.(string)
		el = el.Next()
		rec := q.records[id]
		if rec == nil || isTerminal(rec.Status) {
			continue
		}
		due := rec.Attempts == 0 || retryDue(rec, nowMs)
		if !due {
			continue
		}
		if r, done, err := q.checkReplayExpiry(rec, nowMs); err != nil {
			return nil, err
		} else if done {
			report.Results = append(report.Results, r)
			continue
		}
		r, err := q.processDue(rec, nowMs)
		if err != nil {
			return nil, err
		}
		report.Results = append(report.Results, r)
	}

	// Phase 2: replay/expiry hold for every non-terminal message at the new
	// time, even while its retry backoff is still running. Messages that
	// terminalized in phase 1 are already gone from the list, so this sweep
	// (plus every constant-time unlink it triggers) again costs one linear
	// pass over the remaining live messages only — never over history.
	el = q.order.l.Front()
	for el != nil {
		id := el.Value.(string)
		// Capture the successor before processing: checkReplayExpiry may
		// terminalize — and unlink — this very node.
		el = el.Next()
		rec := q.records[id]
		if rec == nil || isTerminal(rec.Status) {
			continue
		}
		if r, done, err := q.checkReplayExpiry(rec, nowMs); err != nil {
			return nil, err
		} else if done {
			report.Results = append(report.Results, r)
		}
	}

	if err := q.store.appendAdvance(nowMs); err != nil {
		return nil, q.fail("advance", err)
	}
	q.now = nowMs
	if err := q.maybeCompact(); err != nil {
		return nil, err
	}
	return report, nil
}

// maybeCompact rewrites the WAL as a snapshot once it grows past the
// threshold. Live state already reflects every acknowledged append, so the
// snapshot cannot lose records. A compaction failure is a storage failure:
// the queue is marked broken and must be reopened.
func (q *Queue) maybeCompact() error {
	if !q.store.needsCompaction() {
		return nil
	}
	if err := q.store.compact(q.snapshot()); err != nil {
		return q.fail("compact log", err)
	}
	return nil
}

// checkReplayExpiry terminalizes rec when its nonce was consumed by another
// message or its absolute expiry has been reached. Replay wins when both
// hold. The bool reports whether the message was terminalized.
func (q *Queue) checkReplayExpiry(rec *Record, now int64) (Result, bool, error) {
	id := rec.Msg.Message.ID
	token := newConsumeToken(rec.Msg.Message.From, rec.Msg.Message.To, rec.Msg.Message.Nonce)
	if winner, taken := q.consumed[token]; taken && winner != id {
		reason := "nonce combination already consumed by message " + winner
		r, err := q.applyOutcome(rec, now, terminalOutcome(StatusReplay, reason))
		if err != nil {
			return Result{}, false, err
		}
		return r, true, nil
	}
	if rec.Msg.ExpiresAt != 0 && now >= rec.Msg.ExpiresAt {
		reason := "expired at " + strconv.FormatInt(rec.Msg.ExpiresAt, 10)
		r, err := q.applyOutcome(rec, now, terminalOutcome(StatusExpired, reason))
		if err != nil {
			return Result{}, false, err
		}
		return r, true, nil
	}
	return Result{}, false, nil
}

// processDue classifies a due message against source registration and header
// trust, or delivers it.
func (q *Queue) processDue(rec *Record, now int64) (Result, error) {
	m := rec.Msg.Message
	if !q.sources[m.From] {
		reason := "unknown source chain " + m.From
		return q.applyOutcome(rec, now, terminalOutcome(StatusUnknownSrc, reason))
	}
	hs := q.headers[m.From]
	if hs == nil || hs.trusted == nil || hs.trusted.Height < m.ProofAt {
		cur := int64(0)
		if hs != nil && hs.trusted != nil {
			cur = hs.trusted.Height
		}
		reason := fmt.Sprintf("waiting for trusted header covering height %d (current %d)", m.ProofAt, cur)
		return q.applyOutcome(rec, now, waitingOutcome(reason))
	}

	// Deliver: success record and nonce consumption are one log entry. The
	// coverage height is the highest trusted header actually accepted — never
	// a higher untrusted header.
	token := newConsumeToken(m.From, m.To, m.Nonce)
	reason := "delivered; proof verified by trusted header at height " + strconv.FormatInt(hs.trusted.Height, 10)
	return q.applyOutcome(rec, now, successOutcome(reason, token))
}

// outcome describes one processing result independently of which path found
// it: waiting for header coverage, delivery, or one of the terminal rejections
// (replay, expiry, unknown source). It carries only the business differences
// between the result kinds; the rules shared by every result — one more
// attempt, the processing-time stamp, how the result is persisted and when the
// record may change — live solely in applyOutcome.
type outcome struct {
	status string
	reason string
	// consume is set only for success: the message's own
	// (source, destination, nonce) triple, attributed to that message. No
	// other result kind consumes a nonce.
	consume *consumeToken
	// op labels the failing operation in the storage error for this kind of
	// result, keeping each path's historical error wording.
	op string
}

// waitingOutcome keeps the message live with its status unchanged in kind and
// its existing backoff machinery: the actual retry instant is computed by
// applyOutcome from the processing time and the new attempt number.
func waitingOutcome(reason string) outcome {
	return outcome{status: StatusWaiting, reason: reason, op: "schedule retry"}
}

// terminalOutcome settles a non-success result that ends processing: replay,
// expiry or unknown-source. Such results clear the retry schedule, consume no
// nonce and leave the live processing order.
func terminalOutcome(status, reason string) outcome {
	return outcome{status: status, reason: reason, op: "terminalize"}
}

// successOutcome delivers the message: it clears the retry schedule, leaves
// the processing order and records consumption of the message's own triple,
// attributed to the message itself, in the same durable record as the success
// state.
func successOutcome(reason string, token consumeToken) outcome {
	return outcome{status: StatusSuccess, reason: reason, consume: &token, op: "deliver"}
}

// applyOutcome is the single path through which every processing result is
// saved and takes effect. It persists the result first and touches the record
// only after the save is acknowledged, so a failed write changes nothing: the
// message keeps its previous status, reason, attempt count, processing time
// and retry schedule, its nonce is not consumed, and earlier results already
// acknowledged in the same advance stay in force. On success every result
// counts exactly one more attempt and stamps LastProcAt with the processing
// time; a waiting result additionally keeps its saturated backoff schedule,
// while success and terminal results clear the retry time and leave the
// processing order; success also records the nonce consumption.
func (q *Queue) applyOutcome(rec *Record, now int64, oc outcome) (Result, error) {
	id := rec.Msg.Message.ID
	attempt := rec.Attempts + 1
	nextRetry := int64(0)
	if oc.status == StatusWaiting {
		nextRetry = nextRetryAt(now, attempt)
	}
	if err := q.store.appendOutcome(now, rec, attempt, nextRetry, oc); err != nil {
		return Result{}, q.fail(oc.op, err)
	}
	rec.Attempts = attempt
	rec.LastProcAt = now
	rec.Status = oc.status
	rec.Reason = oc.reason
	rec.NextRetry = nextRetry
	if oc.consume != nil {
		q.consumed[*oc.consume] = id
	}
	if isTerminal(oc.status) {
		q.order.remove(id)
	}
	return Result{ID: id, Status: oc.status, Reason: oc.reason}, nil
}

// retryDue reports whether a waiting record's next retry is reached at now.
// Backoff delays are always positive, so every representable retry lies
// strictly after the processing time that scheduled it; a waiting message is
// therefore evaluated at most once per distinct processing time. The only
// instant where the retry cannot lie later is the int64 ceiling: there the
// schedule saturates to the ceiling itself. Once the message was processed at
// the ceiling, every legal advance is at the same instant, so the retry can
// never be reached "later" — treating equal time as due would reprocess the
// message on every advance, inflate attempts and re-report waiting forever.
func retryDue(rec *Record, now int64) bool {
	if now < rec.NextRetry {
		return false
	}
	return now != rec.LastProcAt
}

// nextRetryAt returns the retry instant after the attempt-th processing at
// now: now plus the backoff delay, saturated at math.MaxInt64. Saturation
// keeps the scheduled retry non-negative, never zero (when processed at a
// positive time) and never earlier than the processing time; when the true
// retry overflows int64 the ceiling is the nearest representable instant.
func nextRetryAt(now int64, attempt int) int64 {
	delay := nextRetryDelay(attempt)
	if now > maxProcessTime-delay {
		return maxProcessTime // now+delay would overflow; delay is at most 60000
	}
	return now + delay
}

// nextRetryDelay is the backoff after the attempt-th processing (1-based):
// 1s, 2s, 4s, 8s, 16s, 32s, then 60s capped, in milliseconds.
func nextRetryDelay(attempt int) int64 {
	if attempt < 1 {
		attempt = 1
	}
	if attempt > 6 {
		return 60_000
	}
	return int64(1) << (attempt - 1) * 1000
}

func isTerminal(status string) bool {
	switch status {
	case StatusSuccess, StatusReplay, StatusExpired, StatusUnknownSrc:
		return true
	}
	return false
}

func sameEnvelope(a, b Envelope) bool {
	return a.ExpiresAt == b.ExpiresAt &&
		a.Message.ID == b.Message.ID &&
		a.Message.From == b.Message.From &&
		a.Message.To == b.Message.To &&
		a.Message.Nonce == b.Message.Nonce &&
		a.Message.Payload == b.Message.Payload &&
		a.Message.ProofAt == b.Message.ProofAt
}

// Query returns the current state of a message.
func (q *Queue) Query(id string) (Query, bool) {
	q.mu.Lock()
	defer q.mu.Unlock()
	rec, ok := q.records[id]
	if !ok {
		return Query{}, false
	}
	return toQuery(rec), true
}

// Queries returns all records in first-submission order.
func (q *Queue) Queries() []Query {
	q.mu.Lock()
	defer q.mu.Unlock()
	out := make([]Query, 0, len(q.records))
	for _, rec := range q.records {
		out = append(out, toQuery(rec))
	}
	sort.Slice(out, func(i, j int) bool {
		return q.records[out[i].ID].Seq < q.records[out[j].ID].Seq
	})
	return out
}

// Now returns the last advanced processing time, or 0 if never advanced.
func (q *Queue) Now() int64 {
	q.mu.Lock()
	defer q.mu.Unlock()
	return q.now
}

func toQuery(rec *Record) Query {
	return Query{
		ID:        rec.Msg.Message.ID,
		From:      rec.Msg.Message.From,
		To:        rec.Msg.Message.To,
		Nonce:     rec.Msg.Message.Nonce,
		Payload:   rec.Msg.Message.Payload,
		ProofAt:   rec.Msg.Message.ProofAt,
		ExpiresAt: rec.Msg.ExpiresAt,
		Status:    rec.Status,
		Reason:    rec.Reason,
		NextRetry: rec.NextRetry,
		Attempts:  rec.Attempts,
	}
}

package relayproof

import (
	"bytes"
	"encoding/base64"
	"encoding/binary"
	"encoding/json"
	"errors"
	"fmt"
	"hash/crc32"
	"io"
	"math"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"unicode/utf8"
)

// On-disk format (queue.log):
//
//	magic   = "RELAYPROOF-QUEUE-V1\n"
//	frame   = uint32-be payload length(N) | N bytes JSON payload | uint32-be CRC32-IEEE(payload)
//
// The log is an append-only write-ahead log. Every mutating operation is
// persisted as one framed, checksummed record and fsynced before it is
// acknowledged; a success record frames the local success entry and the nonce
// consumption together, so the two can never take effect separately.
//
// A success (result or compacted state) names the consumed triple in three
// independent fields, consumeFrom/consumeTo/consumeNonce, alongside consumeBy.
// Chain names are stored verbatim as raw UTF-8 — they may contain ':' or even
// U+0000 — so the triple is never flattened into one delimiter-joined string,
// which would let distinct routing paths share one consumption identity.
//
// Crash recovery: a frame missing bytes at end of file, or a final frame with
// a bad checksum, is the torn tail of a write that was never acknowledged and
// is truncated. That recovery is only available once the log's leading
// version record has itself been read whole and verified: the magic alone
// never establishes a usable version, so a log whose very first record is
// partial (only some length bytes, or the length without the body and CRC),
// complete but checksum-bad, not a version record, or names an unsupported
// version is rejected wholesale with ErrCorrupt and left byte-for-byte
// untouched — it can never be truncated down to an empty-looking log that a
// later append would turn into a headerless one. Bad checksums or framing
// anywhere before the end, a foreign header, or an unsupported version
// likewise reject the directory with ErrCorrupt; state is never silently
// cleared.
//
// Logs written by older builds recorded the consumption as one NUL-joined
// consumeKey string. Such success entries are still accepted on replay: the
// key is validated against the record's own (from,to,nonce) and consumeBy,
// and only the record's own triple is marked consumed. A legacy key that does
// not match the record it is attached to — a genuinely inconsistent old
// record — rejects the whole directory with ErrCorrupt instead of silently
// accepting or "repairing" the bad entry.
//
// Header roots are arbitrary byte strings and must survive the log
// byte-for-byte: roots compare as their exact bytes, so two roots that differ
// in any byte are different roots. JSON string encoding silently rewrites
// invalid UTF-8 bytes to U+FFFD, which would merge distinct roots (and make a
// resubmitted original root conflict with its own saved value after a
// reopen). A root that is valid UTF-8 — including the empty root — keeps the
// historical plain "root" field, so existing logs keep their meaning
// byte-for-byte; a root holding invalid UTF-8 bytes is stored base64-encoded
// in "rootB64" instead, preserving the exact byte sequence across save,
// reopen and compaction. Roots an older build already rewrote to replacement
// characters stay those characters on replay — the lost bytes are never
// guessed. The two representations are mutually exclusive by key presence: a
// record that carries "root" and "rootB64" together — even when one is the
// empty string, and even when the two happen to decode to the same bytes — is
// an inconsistent record no build writes and rejects the directory with
// ErrCorrupt. The empty string counts as a present key, so the legal empty
// root ("root":"" alone, or neither key on old records) is never confused
// with a dual-root record.
//
// Message payloads have the same contract and use the same encoding: the Go
// submit interface accepts any string without requiring valid UTF-8 (empty
// text, NUL bytes, stray 0xFF/0xFE bytes or text mixed with them), and a
// payload read back after a reopen or compaction must equal the submitted
// bytes exactly, since payloads participate in same-id content comparison. A
// valid-UTF-8 payload keeps the historical plain "payload" field, so existing
// logs and the CLI stay compatible; an invalid-UTF-8 payload is stored
// base64-encoded in "payloadB64". The bytes 0xFF, 0xFE and the legal
// character U+FFFD are three different payloads and are never conflated.
// Payloads an older build already rewrote to replacement characters stay
// those characters on replay — again, the lost bytes are never guessed. The
// two representations are mutually exclusive by key presence: a record that
// carries "payload" and "payloadB64" together — even when one is the empty
// string, both are empty, or the two happen to decode to the same bytes — is
// an inconsistent record no build writes and rejects the directory with
// ErrCorrupt, regardless of field order. Field-name casing changes nothing:
// encoding/json fills the same struct field from "PAYLOADB64" or a mixed-case
// spelling, so key presence is folded the same way on replay — a sole
// re-cased base64 field still decodes to its exact bytes and a re-cased plain
// field beside a base64 field is still two representations at once. The empty
// string counts as a present key, so the legal empty payload ("payload":""
// alone, a sole empty "payloadB64":"", or neither key on old records) is never
// confused with a dual-payload record. A checksum-valid record carrying an
// undecodable payloadB64 likewise rejects the directory with ErrCorrupt,
// leaving the file untouched — it is never read back as an empty or
// replacement-filled payload.
//
// Destination chain names have the same contract and use the same encoding:
// replay identity is the exact (source chain, destination chain, nonce)
// triple, so a destination name holding invalid UTF-8 bytes must survive as
// those bytes, not as what a display layer happens to render. The Go submit
// interface accepts any non-empty destination without requiring valid UTF-8 —
// text, colons, NUL bytes, stray 0xFF/0xFE bytes or text mixed with them — and
// the bytes 0xFF, 0xFE and the legal character U+FFFD are three different
// destinations that must never merge: after a reopen or compaction a
// byte-identical resubmit must still find its own unterminated record, the
// replay triple it belongs to must stay keyed by the original bytes, and a
// message to the visually similar replacement character must not be mistaken
// for one that consumed the invalid-byte destination. JSON string encoding
// would silently rewrite an invalid destination to U+FFFD in the submit
// entry's "to" and a success entry's "consumeTo", so a valid-UTF-8 destination
// keeps the historical plain fields while an invalid-UTF-8 destination is
// stored base64-encoded in "toB64" and "consumeToB64". Destinations an older
// build already rewrote to replacement characters stay those characters on
// replay — the lost bytes are never guessed. As with the other split fields,
// carrying both representations at once (by key presence, the empty string
// included) or an undecodable base64 value is an inconsistent record that
// rejects the directory with ErrCorrupt.
//
// Source chain names have the same contract and use the same encoding: the
// replay identity's first element is the source chain's exact bytes, source
// registration and trusted-header coverage apply per byte-identical chain,
// and an unknown-source reason quotes the chain. The Go interface accepts any
// non-empty source name without requiring valid UTF-8 — ordinary text,
// colons, NUL bytes, stray 0xFF/0xFE bytes or text mixed with them — and the
// bytes 0xFF, 0xFE and the legal character U+FFFD are three different source
// chains that must never merge: two names that differ only in an invalid byte
// are distinct in the same process, so saving one as the replacement
// character would, after a reopen, mix the two chains' registrations, trusted
// headers and consumed nonces. JSON string encoding would silently rewrite an
// invalid source name in a source or header entry's "chain", a submit entry's
// "from" and a success entry's "consumeFrom", so a valid-UTF-8 name keeps the
// historical plain fields while an invalid-UTF-8 name is stored
// base64-encoded in "chainB64", "fromB64" and "consumeFromB64". Names an
// older build already rewrote to replacement characters stay those characters
// on replay — the lost bytes are never guessed, and a message terminalized by
// such a legacy record is never reactivated. As with the other split fields,
// carrying both representations at once (by key presence, the empty string
// included) or an undecodable base64 value is an inconsistent record that
// rejects the directory with ErrCorrupt.
//
// Message ids have the same contract and use the same encoding: identity is
// judged by the id's exact bytes, never by its display form. The Go submit
// interface accepts any non-empty id without requiring valid UTF-8 — plain
// text, Chinese text, whitespace, colons, NUL bytes, stray 0xFF/0xFE bytes,
// or text mixed with them — and the bytes 0xFF, 0xFE and the legal character
// U+FFFD are three different ids that must never merge into one record. JSON
// string encoding would silently rewrite invalid id bytes to U+FFFD, so after
// a reopen the original id would no longer find its message and two distinct
// ids could replay as duplicate submits, making the directory unopenable. A
// valid-UTF-8 id keeps the historical plain "id" field (and a success entry's
// "consumeBy"), so existing logs and the CLI stay byte-compatible; an
// invalid-UTF-8 id is stored base64-encoded in "idB64" (and "consumeByB64").
// Result and snapshot reasons embed such raw bytes too — a replay reason
// names the winning message id and an unknown-source reason names the chain —
// so an invalid-UTF-8 reason is likewise stored in "reasonB64". Ids an older
// build already rewrote to replacement characters stay those characters on
// replay; the lost bytes are never guessed. A record carrying both a plain
// field and its base64 form, or an undecodable base64 field, is corrupt and
// rejects the directory with ErrCorrupt.
//
// Processing-time validation on replay: a plain result's time must be a
// non-negative Unix-millisecond instant and no earlier than any queue-wide
// time the log has already confirmed — an advance checkpoint or any earlier
// result or snapshot, of any message — because no legal advance can produce
// an outcome stamped before the time the queue had already reached. A
// due-result (success or waiting) of an already processed message must
// additionally respect that message's own retry schedule: it may only be
// stamped at a distinct processing instant at or after the retry its last
// result scheduled, however intact and well-checksummed the record is —
// replaying an early success would otherwise consume a nonce that normal
// advances could not. Replay and expired results are not bounded by the
// schedule: phase-2 replay/expiry holds settle a waiting message while its
// backoff is still running. A compacted snapshot's time must likewise be
// non-negative, but snapshots need not be time-ordered among themselves:
// each records its own message's last processing instant in first-submission
// order. A complete, checksum-valid record that violates these rules is
// corrupt (ErrCorrupt), never a truncatable torn tail, so the log's length
// and bytes are preserved.
//
// Source-registration validation on replay: a success — a plain result or a
// compacted state — is a recorded delivery, so just like a live advance it is
// only legal when the message's own source chain was registered. A saved
// trusted header never stands in for registration: normal processing
// terminalizes an unregistered source as unknown-source however high its
// trusted coverage is, so recovery must not resurrect such a message as
// success and consume its nonce. For a plain result only registrations saved
// in earlier records count, so a source registered after the success was
// recorded can never retroactively legalize it; a compacted state is judged
// against the registrations the snapshot retained (compaction writes them
// before the records), with no reconstruction of compacted-away registration
// history. Registering another chain never covers the message — chain names
// are their raw bytes, never their display form. A complete, checksum-valid
// success from an unregistered source is corrupt (ErrCorrupt), never a
// truncatable torn tail, so the log's length and bytes are preserved.
//
// Trusted-coverage validation on replay: a success — a plain result or a
// compacted state — is a recorded delivery, so just like a live advance it is
// only legal when the message's own source chain has a trusted header at least
// at its proof height. For a plain result only headers saved in earlier
// records count, so a trusted header written after the success can never
// retroactively cover it; a compacted state is judged against the trusted
// coverage the snapshot retained, with no reconstruction of compacted-away
// header history. Another chain's trusted headers never cover the message —
// chains are their raw bytes — untrusted headers at any height never establish
// coverage, a lower trusted header never narrows it, and a trusted height
// exactly equal to the proof height does cover. The saved reason text never
// stands in for a saved trusted header and need not name the retained highest
// trusted height. A complete, checksum-valid success that lacks coverage is
// corrupt (ErrCorrupt), never a truncatable torn tail, so the log's length
// and bytes are preserved.

const (
	logName          = "queue.log"
	logMagic         = "RELAYPROOF-QUEUE-V1\n"
	compactThreshold = 4 << 20 // compact when the active log grows past 4 MiB
	compactFileMode  = 0o600
	frameHeaderSize  = 4
	frameCRCsSize    = 4
)

var crcTable = crc32.MakeTable(crc32.IEEE)

// JSON log entry kinds.
const (
	kindVersion = "version"
	kindSource  = "source"
	kindHeader  = "header"
	kindSubmit  = "submit"
	kindResult  = "result"
	kindState   = "state" // compacted snapshot: full status after >=1 attempts
	kindAdvance = "advance"
	currentLogV = 1
)

type logEntry struct {
	T string `json:"t"`
	V int    `json:"v,omitempty"`

	Chain   string `json:"chain,omitempty"`
	Height  int64  `json:"height,omitempty"`
	Root    string `json:"root,omitempty"`
	Trusted bool   `json:"trusted,omitempty"`

	// ChainB64 carries a source/header entry's chain name raw bytes
	// base64-encoded when the name is not valid UTF-8; see setChain/entryChain.
	// Never set together with Chain.
	ChainB64 string `json:"chainB64,omitempty"`

	// RootB64 carries a header root's raw bytes base64-encoded when the root
	// is not valid UTF-8; see setRoot/headerRoot. Never set together with
	// Root.
	RootB64 string `json:"rootB64,omitempty"`

	Seq       int64  `json:"seq,omitempty"`
	ID        string `json:"id,omitempty"`
	From      string `json:"from,omitempty"`
	To        string `json:"to,omitempty"`
	Nonce     uint64 `json:"nonce,omitempty"`
	Payload   string `json:"payload,omitempty"`
	ProofAt   int64  `json:"proofAt,omitempty"`
	ExpiresAt int64  `json:"expiresAt,omitempty"`

	// ToB64 carries a submit entry's destination chain raw bytes base64-encoded
	// when the destination is not valid UTF-8; see setTo/entryTo. Never set
	// together with To.
	ToB64 string `json:"toB64,omitempty"`

	// FromB64 carries a submit entry's source chain raw bytes base64-encoded
	// when the source is not valid UTF-8; see setFrom/entryFrom. Never set
	// together with From.
	FromB64 string `json:"fromB64,omitempty"`

	// IDB64 carries a message id's raw bytes base64-encoded when the id is
	// not valid UTF-8; see setID/entryID. Never set together with ID.
	IDB64 string `json:"idB64,omitempty"`

	// PayloadB64 carries a message payload's raw bytes base64-encoded when the
	// payload is not valid UTF-8; see setPayload/entryPayload. Never set
	// together with Payload.
	PayloadB64 string `json:"payloadB64,omitempty"`

	Now       int64  `json:"now,omitempty"`
	Status    string `json:"status,omitempty"`
	Reason    string `json:"reason,omitempty"`
	Attempts  int    `json:"attempts,omitempty"`
	NextRetry int64  `json:"nextRetry,omitempty"`

	// ReasonB64 carries a result/snapshot reason's raw bytes base64-encoded
	// when the reason is not valid UTF-8 (it may embed a raw-bytes message id
	// or chain name); see setReason/entryReason. Never set together with
	// Reason.
	ReasonB64 string `json:"reasonB64,omitempty"`

	// Consumed triple of a success entry, stored as three independent values
	// so routing paths that share a flattened key stay distinct. consumeBy is
	// the id of the successful message.
	ConsumeFrom  string `json:"consumeFrom,omitempty"`
	ConsumeTo    string `json:"consumeTo,omitempty"`
	ConsumeNonce uint64 `json:"consumeNonce,omitempty"`
	ConsumeBy    string `json:"consumeBy,omitempty"`

	// ConsumeToB64 is the base64 form of ConsumeTo for an invalid-UTF-8
	// destination chain; see setConsumeTo/entryConsumeTo. Never set together
	// with ConsumeTo.
	ConsumeToB64 string `json:"consumeToB64,omitempty"`

	// ConsumeFromB64 is the base64 form of ConsumeFrom for an invalid-UTF-8
	// source chain; see setConsumeFrom/entryConsumeFrom. Never set together
	// with ConsumeFrom.
	ConsumeFromB64 string `json:"consumeFromB64,omitempty"`

	// ConsumeByB64 is the base64 form of ConsumeBy for an invalid-UTF-8
	// message id; see setConsumeBy/entryConsumeBy. Never set together with
	// ConsumeBy.
	ConsumeByB64 string `json:"consumeByB64,omitempty"`

	// ConsumeKey is the legacy (pre-triple) NUL-joined consumption string. It
	// is accepted only while replaying logs written by older builds and is
	// never written anymore.
	ConsumeKey string `json:"consumeKey,omitempty"`

	// present records which JSON keys the replayed record literally carried,
	// for the plain/base64-split fields — root/rootB64, payload/payloadB64,
	// to/toB64, from/fromB64, chain/chainB64, consumeTo/consumeToB64 and
	// consumeFrom/consumeFromB64. The split's mutual-exclusion and empty-value rules are keyed on presence, not the decoded value: the
	// empty string is a legal value and is written as an explicitly present
	// "…":"", so it must never double as the signal that the key was omitted.
	// Set only by UnmarshalJSON and never marshalled.
	present map[string]bool
}

// splitJSONKeys are the plain/base64 field pairs whose mutual-exclusion rule
// is keyed on literal JSON key presence (see logEntry.present and
// splitFieldSpec). Field order in the record is irrelevant.
var splitJSONKeys = []string{
	"root", "rootB64",
	"payload", "payloadB64",
	"to", "toB64",
	"from", "fromB64",
	"chain", "chainB64",
	"consumeTo", "consumeToB64",
	"consumeFrom", "consumeFromB64",
}

// UnmarshalJSON decodes a log record while recording which plain/base64 keys
// the record literally carried. The plain/base64 split needs presence, not
// just the decoded value: the empty root/payload is a legal value written as
// "root":""/"payload":"", so the empty string cannot double as the signal
// that the key was omitted. The exported fields decode exactly as with the
// default unmarshalling (the alias avoids listing them by hand); only the
// presence map is extra.
//
// Presence is matched case-insensitively — with strings.EqualFold, the same
// folding encoding/json uses when selecting a struct field for a JSON key —
// because the struct value and the presence map must describe the same key.
// The struct decoder fills PayloadB64 from a key spelled "PAYLOADB64" or
// "PayloadB64"; a literal lookup would miss it, so a sole re-cased base64 key
// would be mistaken for an omitted one (its decoded bytes silently dropped to
// the empty plain value) and a re-cased plain key alongside a normal base64
// key would no longer read as two representations at once. Canonicalizing the
// literal keys keeps the verdict identical across every casing.
func (e *logEntry) UnmarshalJSON(data []byte) error {
	type plain logEntry
	var p plain
	if err := json.Unmarshal(data, &p); err != nil {
		return err
	}
	*e = logEntry(p)
	var keys map[string]json.RawMessage
	if err := json.Unmarshal(data, &keys); err != nil {
		return err
	}
	e.present = make(map[string]bool, len(splitJSONKeys))
	for literal := range keys {
		for _, canonical := range splitJSONKeys {
			if strings.EqualFold(literal, canonical) {
				e.present[canonical] = true
				break
			}
		}
	}
	return nil
}

// splitFieldSpec is one plain/base64 field pair's descriptor: the JSON key
// names, ways to read and write the two slots on a log entry, and the field's
// own wording for the two corruption verdicts. Every pair shares exactly one
// byte-preservation rule set — the write half in encode and the read half in
// decode, each implemented once — and differs only in this descriptor, so
// each value keeps its business meaning (message id, processing reason,
// header root, message payload, source and destination chains, and the
// success entry's consumed triple) and its existing, field-specific error
// text. Adding another raw-bytes field means adding one descriptor, not
// another copy of the UTF-8/base64 or presence/empty/decode handling.
//
// plainKey is empty for fields that predate presence tracking (id/idB64,
// reason/reasonB64, consumeBy/consumeByB64): those pairs keep their historical
// value-based mutual exclusion (they are never written with an empty plain
// value), which decode applies when plainKey is empty.
type splitFieldSpec struct {
	plainKey       string
	b64Key         string
	plain          func(e *logEntry) string
	b64            func(e *logEntry) string
	set            func(e *logEntry, plain, b64 string)
	bothErr        string
	undecodableErr string
}

// decode is the single inverse of the plain/base64 field split every raw-bytes
// log value uses. The rules are:
//
//   - With the base64 key absent, the plain value is taken at face value. That
//     covers historical records that predate the split, including bytes an old
//     build rewrote to U+FFFD: the saved characters stay literal and are never
//     guessed back.
//   - With the base64 key present (alone, including an empty base64 string),
//     the base64 value is decoded to the original byte sequence.
//   - Both representations present is an inconsistent record no build writes —
//     judged by key presence where tracked, so even "":"" or two forms that
//     decode to the identical bytes clash — regardless of field order.
//   - A present base64 value that does not decode is corruption, never an empty
//     or replacement-filled value.
func (s splitFieldSpec) decode(e *logEntry) (string, error) {
	b64Value := s.b64(e)
	var b64Present bool
	if s.plainKey != "" {
		// Presence-based mutual exclusion: the empty string counts as present.
		if e.present[s.plainKey] && e.present[s.b64Key] {
			return "", errors.New(s.bothErr)
		}
		b64Present = e.present[s.b64Key]
	} else {
		// Historical value-based mutual exclusion for fields whose plain value
		// is never written empty alongside a base64 form: a set plain value
		// with a set base64 value clashes; an empty base64 is simply absent.
		if s.plain(e) != "" && b64Value != "" {
			return "", errors.New(s.bothErr)
		}
		b64Present = b64Value != ""
	}
	if !b64Present {
		return s.plain(e), nil
	}
	raw, err := base64.StdEncoding.DecodeString(b64Value)
	if err != nil {
		return "", fmt.Errorf("%s: %v", s.undecodableErr, err)
	}
	return string(raw), nil
}

// encode is the single write half of the plain/base64 field split every
// raw-bytes log value uses, the exact inverse of decode:
//
//   - A value that is valid UTF-8 is written to the plain slot unchanged, so
//     ordinary text, Chinese, colons, whitespace and U+0000 keep the
//     historical plain field (the empty value included), and existing logs
//     stay byte-compatible.
//   - A value holding invalid UTF-8 bytes would be silently rewritten to
//     U+FFFD by JSON string encoding, so it is base64-encoded into the b64
//     slot instead, preserving the exact byte sequence across save, reopen
//     and compaction.
//
// The two slots are always written through set together, so one field can
// never carry both representations at once: the slot the value does not use
// is cleared. The rule takes no position on what the bytes mean — that is the
// caller's field — it only chooses the representation.
func (s splitFieldSpec) encode(e *logEntry, value string) {
	if utf8.ValidString(value) {
		s.set(e, value, "")
		return
	}
	s.set(e, "", base64.StdEncoding.EncodeToString([]byte(value)))
}

