// Command relayproof is the 跨链消息与轻客户端验证服务 entry point.
package main

import (
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"os"

	"github.com/asdhoaiqqq/relayproof-bridge/relayproof"
)

func main() {
	if len(os.Args) < 2 {
		runDemo()
		return
	}
	switch os.Args[1] {
	case "demo":
		runDemo()
	case "version":
		fmt.Println("relayproof 0.2.0")
	case "queue":
		runQueue(os.Args[2:])
	case "verify":
		if err := runVerify(os.Args[2:]); err != nil {
			fmt.Fprintf(os.Stderr, "error: %v\n", err)
			os.Exit(1)
		}
	case "help", "-h", "--help":
		usage()
	default:
		fmt.Fprintf(os.Stderr, "unknown command %q\n", os.Args[1])
		usage()
		os.Exit(2)
	}
}

func usage() {
	fmt.Println(`usage: relayproof <command> [flags]

commands:
  demo                         run the in-memory verification demo
  version                      print version
  queue                        manage the durable local message queue
  verify [--state DIR]         run the deterministic end-to-end verification
  help                         show this help

queue subcommands (all take --state DIR):
  register-source --chain C
  header --chain C --height N --root R [--trusted]
  submit --id ID --from C --to C --nonce N --proof-at H --payload P [--expires-at MS]
  advance --now MS
  query [--id ID]

times are Unix milliseconds; --expires-at 0 (default) means never expire.`)
}

func runQueue(args []string) {
	if len(args) == 0 {
		fmt.Fprintln(os.Stderr, "queue requires a subcommand: register-source|header|submit|advance|query")
		os.Exit(2)
	}
	sub, rest := args[0], args[1:]
	var err error
	switch sub {
	case "register-source":
		err = queueCmdRegisterSource(rest)
	case "header":
		err = queueCmdHeader(rest)
	case "submit":
		err = queueCmdSubmit(rest)
	case "advance":
		err = queueCmdAdvance(rest)
	case "query":
		err = queueCmdQuery(rest)
	default:
		fmt.Fprintf(os.Stderr, "unknown queue subcommand %q\n", sub)
		os.Exit(2)
	}
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(exitCode(err))
	}
}

func exitCode(err error) int {
	switch {
	case errors.Is(err, relayproof.ErrLocked):
		return 11
	case errors.Is(err, relayproof.ErrCorrupt):
		return 12
	case errors.Is(err, relayproof.ErrConflict):
		return 13
	case errors.Is(err, relayproof.ErrHeaderConflict):
		return 16
	case errors.Is(err, relayproof.ErrTerminal):
		return 14
	case errors.Is(err, relayproof.ErrInvalidArg):
		return 2
	case errors.Is(err, relayproof.ErrStorage):
		return 15
	default:
		return 1
	}
}

type globalFlags struct {
	state string
}

func newQueueFlagSet(name string, g *globalFlags) *flag.FlagSet {
	fs := flag.NewFlagSet(name, flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	fs.StringVar(&g.state, "state", "", "state directory (required)")
	return fs
}

func (g *globalFlags) mustState() {
	if g.state == "" {
		fmt.Fprintln(os.Stderr, "error: --state is required")
		os.Exit(2)
	}
}

func queueCmdRegisterSource(rest []string) error {
	g := &globalFlags{}
	fs := newQueueFlagSet("register-source", g)
	chain := fs.String("chain", "", "source chain name (required)")
	if err := fs.Parse(rest); err != nil {
		return err
	}
	if *chain == "" {
		return fmt.Errorf("%w: --chain is required", relayproof.ErrInvalidArg)
	}
	g.mustState()
	q, err := relayproof.Open(g.state)
	if err != nil {
		return err
	}
	defer q.Close()
	if err := q.RegisterSource(*chain); err != nil {
		return err
	}
	fmt.Printf("registered source chain %s\n", *chain)
	return nil
}

func queueCmdHeader(rest []string) error {
	g := &globalFlags{}
	fs := newQueueFlagSet("header", g)
	chain := fs.String("chain", "", "chain name (required)")
	height := fs.Int64("height", -1, "header height (required)")
	root := fs.String("root", "", "header commitment root")
	trusted := fs.Bool("trusted", false, "mark the header as trusted")
	if err := fs.Parse(rest); err != nil {
		return err
	}
	if *chain == "" || *height < 0 {
		return fmt.Errorf("%w: --chain and non-negative --height are required", relayproof.ErrInvalidArg)
	}
	g.mustState()
	q, err := relayproof.Open(g.state)
	if err != nil {
		return err
	}
	defer q.Close()
	h := relayproof.Header{Chain: *chain, Height: *height, Root: *root, Trusted: *trusted}
	if err := q.UpsertHeader(h); err != nil {
		return err
	}
	fmt.Printf("stored header chain=%s height=%d trusted=%t\n", *chain, *height, *trusted)
	return nil
}

func queueCmdSubmit(rest []string) error {
	g := &globalFlags{}
	fs := newQueueFlagSet("submit", g)
	id := fs.String("id", "", "message id (required)")
	from := fs.String("from", "", "source chain (required)")
	to := fs.String("to", "", "destination chain (required)")
	nonce := fs.Uint64("nonce", 0, "message nonce on the source chain")
	payload := fs.String("payload", "", "message payload")
	proofAt := fs.Int64("proof-at", -1, "height at which the message is proven (required)")
	expiresAt := fs.Int64("expires-at", 0, "absolute expiry as Unix ms; 0 means never")
	if err := fs.Parse(rest); err != nil {
		return err
	}
	if *id == "" || *from == "" || *to == "" || *proofAt < 0 {
		return fmt.Errorf("%w: --id, --from, --to and non-negative --proof-at are required", relayproof.ErrInvalidArg)
	}
	g.mustState()
	q, err := relayproof.Open(g.state)
	if err != nil {
		return err
	}
	defer q.Close()
	rec, err := q.Submit(relayproof.Envelope{
		Message: relayproof.Message{
			ID: *id, From: *from, To: *to, Nonce: *nonce,
			Payload: *payload, ProofAt: *proofAt,
		},
		ExpiresAt: *expiresAt,
	})
	if err != nil {
		return err
	}
	return emitJSON(recordJSON(rec))
}

func queueCmdAdvance(rest []string) error {
	g := &globalFlags{}
	fs := newQueueFlagSet("advance", g)
	now := fs.Int64("now", -1, "processing time as Unix milliseconds (required)")
	if err := fs.Parse(rest); err != nil {
		return err
	}
	if *now < 0 {
		return fmt.Errorf("%w: non-negative --now is required", relayproof.ErrInvalidArg)
	}
	g.mustState()
	q, err := relayproof.Open(g.state)
	if err != nil {
		return err
	}
	defer q.Close()
	report, err := q.Advance(*now)
	if err != nil {
		return err
	}
	return emitJSON(advanceJSON(report))
}

func queueCmdQuery(rest []string) error {
	g := &globalFlags{}
	fs := newQueueFlagSet("query", g)
	id := fs.String("id", "", "message id; omit to list all records in submission order")
	if err := fs.Parse(rest); err != nil {
		return err
	}
	g.mustState()
	q, err := relayproof.Open(g.state)
	if err != nil {
		return err
	}
	defer q.Close()
	if *id != "" {
		rec, ok := q.Query(*id)
		if !ok {
			return fmt.Errorf("no record for message %q", *id)
		}
		return emitJSON(queryJSON(rec))
	}
	for _, rec := range q.Queries() {
		if err := emitJSON(queryJSON(rec)); err != nil {
			return err
		}
	}
	return nil
}

type jsonRecord struct {
	ID        string `json:"id"`
	Status    string `json:"status"`
	Reason    string `json:"reason"`
	Attempts  int    `json:"attempts"`
	NextRetry int64  `json:"nextRetryMs,omitempty"`
	ExpiresAt int64  `json:"expiresAtMs,omitempty"`
}

func recordJSON(r *relayproof.Record) jsonRecord {
	return jsonRecord{
		ID: r.Msg.Message.ID, Status: r.Status, Reason: r.Reason,
		Attempts: r.Attempts, NextRetry: r.NextRetry, ExpiresAt: r.Msg.ExpiresAt,
	}
}

type jsonQuery struct {
	ID        string `json:"id"`
	From      string `json:"from"`
	To        string `json:"to"`
	Nonce     uint64 `json:"nonce"`
	Payload   string `json:"payload"`
	ProofAt   int64  `json:"proofAtHeight"`
	ExpiresAt int64  `json:"expiresAtMs,omitempty"`
	Status    string `json:"status"`
	Reason    string `json:"reason"`
	Attempts  int    `json:"attempts"`
	NextRetry int64  `json:"nextRetryMs,omitempty"`
}

func queryJSON(q relayproof.Query) jsonQuery {
	return jsonQuery{
		ID: q.ID, From: q.From, To: q.To, Nonce: q.Nonce, Payload: q.Payload,
		ProofAt: q.ProofAt, ExpiresAt: q.ExpiresAt, Status: q.Status,
		Reason: q.Reason, Attempts: q.Attempts, NextRetry: q.NextRetry,
	}
}

type jsonAdvance struct {
	NowMs   int64               `json:"nowMs"`
	Results []relayproof.Result `json:"results"`
}

func advanceJSON(r *relayproof.AdvanceReport) jsonAdvance {
	return jsonAdvance{NowMs: r.Now, Results: r.Results}
}

func emitJSON(v any) error {
	enc := json.NewEncoder(os.Stdout)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(v); err != nil {
		return fmt.Errorf("encode output: %w", err)
	}
	return nil
}

func runDemo() {
	headers := map[string]relayproof.Header{
		"chain-a": {Chain: "chain-a", Height: 1024, Root: "0xabc", Trusted: true},
	}
	consumed := map[string]bool{}
	messages := []relayproof.Message{
		{ID: "msg-1", From: "chain-a", To: "chain-b", Nonce: 7, ProofAt: 1000},
		{ID: "msg-2", From: "chain-c", To: "chain-b", Nonce: 1, ProofAt: 10},
	}
	for _, message := range messages {
		delivery := relayproof.Verify(headers, message, consumed)
		fmt.Printf("message=%s status=%s reason=%s\n", delivery.Message, delivery.Status, delivery.Reason)
	}
	replay := relayproof.Verify(headers, messages[0], consumed)
	fmt.Printf("replay of %s status=%s reason=%s\n", replay.Message, replay.Status, replay.Reason)
	fmt.Println("pending:", relayproof.Pending(headers, messages))
}

package relayproof

import (
	"errors"
	"strings"
	"testing"
)

// These tests pin down the processing-time validation applied when an
// existing log is opened. A plain result entry is one incremental outcome of
// a legal advance, so its time must be a non-negative Unix-millisecond
// instant and can never predate any queue-wide time the log has already
// confirmed — an advance checkpoint or any earlier result or snapshot, of any
// message, whether or not a later checkpoint was saved. A compacted snapshot
// only needs the non-negativity floor: compaction writes snapshots in
// first-submission order, each stamped with its own message's last processing
// instant, so their times are legitimately unordered. Every violation is
// ErrCorrupt naming the record category, the message id and the bad time, and
// the log keeps its exact length and bytes even when the bad record is the
// very last one.

// successResultEntry is a well-formed success result for id at now, consuming
// its own triple. Callers mutate copies.
func successResultEntry(id string, now int64) *logEntry {
	return &logEntry{
		T: kindResult, Now: now, ID: id, Status: StatusSuccess,
		Reason:   "delivered; proof verified by trusted header at height 100",
		Attempts: 1, ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1, ConsumeBy: id,
	}
}

// A result stamped before the queue-wide time the log has already confirmed
// is an outcome no legal advance can have produced: normal advances never
// move processing time backwards, so such a record — however complete and
// well-checksummed — must not be recovered as a success (consuming its
// nonce), a waiting schedule or a terminal state.
func TestResultTimeMustNotPredateConfirmedTime(t *testing.T) {
	base := func() []*logEntry {
		return []*logEntry{
			{T: kindSource, Chain: "a"},
			{T: kindHeader, Chain: "a", Height: 100, Root: "0x100", Trusted: true},
			{T: kindSubmit, Seq: 0, ID: "m1", From: "a", To: "b", Nonce: 1, ProofAt: 10},
		}
	}

	t.Run("first success below a saved advance checkpoint", func(t *testing.T) {
		entries := append(base(),
			&logEntry{T: kindAdvance, Now: 5000},
			&logEntry{T: kindSubmit, Seq: 1, ID: "m2", From: "a", To: "b", Nonce: 2, ProofAt: 10},
		)
		bad := successResultEntry("m2", 4000)
		bad.ConsumeNonce = 2
		entries = append(entries, bad)
		assertRecoveryCorrupt(t, entries, "result time 4000 before known time 5000", `"m2"`)
	})

	t.Run("first result below another message's result", func(t *testing.T) {
		entries := append(base(),
			&logEntry{T: kindSubmit, Seq: 1, ID: "m2", From: "a", To: "b", Nonce: 2, ProofAt: 10},
			&logEntry{T: kindResult, Now: 5000, ID: "m1", Status: StatusWaiting,
				Reason: "waiting", Attempts: 1, NextRetry: 6000},
			&logEntry{T: kindResult, Now: 4000, ID: "m2", Status: StatusWaiting,
				Reason: "waiting", Attempts: 1, NextRetry: 5000},
		)
		assertRecoveryCorrupt(t, entries, "result time 4000 before known time 5000", `"m2"`)
	})

	t.Run("first result below an uncheckpointed snapshot", func(t *testing.T) {
		// The previous message's 6000ms state was saved in full but this
		// round's advance checkpoint was not; the saved result still confirms
		// the queue had reached 6000, so a 5500ms outcome is corrupt.
		entries := append(base(),
			&logEntry{T: kindState, Now: 6000, ID: "m1", Status: StatusSuccess,
				Reason: "delivered", Attempts: 1,
				ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1, ConsumeBy: "m1"},
			&logEntry{T: kindSubmit, Seq: 1, ID: "m2", From: "a", To: "b", Nonce: 2, ProofAt: 10},
			&logEntry{T: kindResult, Now: 5500, ID: "m2", Status: StatusWaiting,
				Reason: "waiting", Attempts: 1, NextRetry: 6500},
		)
		assertRecoveryCorrupt(t, entries, "result time 5500 before known time 6000", `"m2"`)
	})

	t.Run("terminal result is bounded too", func(t *testing.T) {
		entries := append(base(),
			successResultEntry("m1", 5000),
			&logEntry{T: kindSubmit, Seq: 1, ID: "m2", From: "a", To: "b", Nonce: 2, ProofAt: 10, ExpiresAt: 4500},
			&logEntry{T: kindResult, Now: 4000, ID: "m2", Status: StatusExpired,
				Reason: "expired at 4500", Attempts: 1},
		)
		assertRecoveryCorrupt(t, entries, "result time 4000 before known time 5000", `"m2"`)
	})

	t.Run("equal time across messages is legal", func(t *testing.T) {
		dir := t.TempDir()
		entries := append(base(),
			&logEntry{T: kindSubmit, Seq: 1, ID: "m2", From: "a", To: "b", Nonce: 2, ProofAt: 10},
			&logEntry{T: kindResult, Now: 5000, ID: "m1", Status: StatusWaiting,
				Reason: "waiting", Attempts: 1, NextRetry: 6000},
			&logEntry{T: kindResult, Now: 5000, ID: "m2", Status: StatusWaiting,
				Reason: "waiting", Attempts: 1, NextRetry: 6000},
			&logEntry{T: kindAdvance, Now: 5000},
		)
		writeLegacyLog(t, dir, entries...)
		q, err := Open(dir)
		if err != nil {
			t.Fatalf("equal-time results must open: %v", err)
		}
		defer q.Close()
		for _, id := range []string{"m1", "m2"} {
			if r := statusOf(t, q, id); r.Status != StatusWaiting || r.Attempts != 1 || r.NextRetry != 6000 {
				t.Fatalf("equal-time result for %s not restored: %+v", id, r)
			}
		}
	})
}

// Neither kind of post-processing record may carry a negative processing
// time; zero remains a valid instant.
func TestRecoveryTimeMustBeNonNegative(t *testing.T) {
	t.Run("waiting result", func(t *testing.T) {
		r := waitingRecoveryRecord(kindResult)
		r.Now, r.NextRetry = -1000, 0
		assertRecoveryCorrupt(t, append(waitingRecoveryBase(), r), "result time -1000 is negative", `"w"`)
	})
	t.Run("success result", func(t *testing.T) {
		r := successRecoveryRecord(kindResult)
		r.Now = -1
		assertRecoveryCorrupt(t, append(successRecoveryBase(), r), "result time -1 is negative", `"m"`)
	})
	t.Run("terminal result", func(t *testing.T) {
		r := terminalRecoveryRecord(kindResult)
		r.Now = -1
		assertRecoveryCorrupt(t, append(terminalRecoveryBase(), r), "result time -1 is negative", `"t"`)
	})
	t.Run("waiting state", func(t *testing.T) {
		r := waitingRecoveryRecord(kindState)
		r.Now, r.NextRetry = -1000, 0
		assertRecoveryCorrupt(t, append(waitingRecoveryBase(), r), "state time -1000 is negative", `"w"`)
	})
	t.Run("success state", func(t *testing.T) {
		r := successRecoveryRecord(kindState)
		r.Now = -1
		assertRecoveryCorrupt(t, append(successRecoveryBase(), r), "state time -1 is negative", `"m"`)
	})

	t.Run("zero is a valid first processing time", func(t *testing.T) {
		dir := t.TempDir()
		entries := append(waitingRecoveryBase(),
			&logEntry{T: kindResult, Now: 0, ID: "w", Status: StatusWaiting,
				Reason: "waiting", Attempts: 1, NextRetry: 1000},
			&logEntry{T: kindAdvance, Now: 0},
		)
		writeLegacyLog(t, dir, entries...)
		q, err := Open(dir)
		if err != nil {
			t.Fatalf("zero as a first processing time must open: %v", err)
		}
		defer q.Close()
		if r := statusOf(t, q, "w"); r.Status != StatusWaiting || r.Attempts != 1 || r.NextRetry != 1000 {
			t.Fatalf("zero-time first result not restored: %+v", r)
		}
	})

	t.Run("zero is a valid first terminal time", func(t *testing.T) {
		dir := t.TempDir()
		entries := append(successRecoveryBase(),
			&logEntry{T: kindResult, Now: 0, ID: "m", Status: StatusSuccess,
				Reason:   "delivered; proof verified by trusted header at height 100",
				Attempts: 1, ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1, ConsumeBy: "m"},
			&logEntry{T: kindAdvance, Now: 0},
		)
		writeLegacyLog(t, dir, entries...)
		q, err := Open(dir)
		if err != nil {
			t.Fatalf("zero-time first success must open: %v", err)
		}
		defer q.Close()
		if r := statusOf(t, q, "m"); r.Status != StatusSuccess || r.Attempts != 1 {
			t.Fatalf("zero-time success not restored: %+v", r)
		}
	})
}

// A compacted log stores each message's last processing instant in
// first-submission order, which is not time order: a first-submitted message
// last processed at 6000 followed by a later-submitted one last processed at
// 2000 is a legitimate state. It must open with every status, reason, attempt
// count and retry schedule intact, and the recovered queue time is the
// maximum of the saved instants and the checkpoint, so nothing appended
// afterwards may be stamped earlier.
func TestCompactedSnapshotsKeepUnorderedTimes(t *testing.T) {
	dir := t.TempDir()
	entries := []*logEntry{
		{T: kindSource, Chain: "a"},
		// Snapshot retains trusted coverage at 100: m1 (proof 10) is covered,
		// m2 (proof 200) is still legitimately waiting at compaction time.
		{T: kindHeader, Chain: "a", Height: 100, Root: "0x100", Trusted: true},
		{T: kindSubmit, Seq: 0, ID: "m1", From: "a", To: "b", Nonce: 1, ProofAt: 10},
		{T: kindState, Now: 6000, ID: "m1", Status: StatusSuccess,
			Reason: "delivered; proof verified by trusted header at height 100", Attempts: 3,
			ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1, ConsumeBy: "m1"},
		{T: kindSubmit, Seq: 1, ID: "m2", From: "a", To: "b", Nonce: 2, ProofAt: 200},
		{T: kindState, Now: 2000, ID: "m2", Status: StatusWaiting,
			Reason: "waiting for trusted header covering height 200 (current 100)", Attempts: 1, NextRetry: 3000},
		{T: kindAdvance, Now: 6000},
	}
	writeLegacyLog(t, dir, entries...)

	q, err := Open(dir)
	if err != nil {
		t.Fatalf("unordered snapshot times must open: %v", err)
	}
	defer q.Close()
	if r := statusOf(t, q, "m1"); r.Status != StatusSuccess || r.Attempts != 3 ||
		!strings.Contains(r.Reason, "delivered") {
		t.Fatalf("success snapshot not restored: %+v", r)
	}
	if r := statusOf(t, q, "m2"); r.Status != StatusWaiting || r.Attempts != 1 || r.NextRetry != 3000 ||
		!strings.Contains(r.Reason, "height 200") {
		t.Fatalf("waiting snapshot not restored: %+v", r)
	}
	if winner := q.consumed[newConsumeToken("a", "b", 1)]; winner != "m1" {
		t.Fatalf("consumption not restored: %q", winner)
	}
	// The queue time is the maximum of the saved instants and the checkpoint;
	// an earlier advance is rejected, an equal one proceeds normally.
	if q.Now() != 6000 {
		t.Fatalf("recovered queue time = %d, want 6000", q.Now())
	}
	if _, err := q.Advance(5999); !errors.Is(err, ErrInvalidArg) {
		t.Fatalf("advance below recovered time: want ErrInvalidArg, got %v", err)
	}
	if _, err := q.Advance(6000); err != nil {
		t.Fatal(err)
	}
	if r := statusOf(t, q, "m2"); r.Status != StatusWaiting || r.Attempts != 2 || r.NextRetry != 8000 {
		t.Fatalf("waiting message did not continue from its restored schedule: %+v", r)
	}
}

package main

// End-to-end behaviour when a state directory's queue.log records a waiting
// result and then a success stamped before that message's scheduled retry.
// The record is complete and checksum-valid, and every other recovery rule
// passes, but no normal advance could have delivered the message — and
// consumed its nonce — while the backoff was still running. Opening the
// directory must fail with the corrupt exit code 12, print no query records
// (including none for an unrelated, fully valid message earlier in the log),
// explain the retry-timing violation on stderr, and leave queue.log
// byte-for-byte untouched.

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// cliEarlySuccessLog is a valid version record followed by: a registered
// source with a covering trusted header, a fully delivered message m0, and
// message w which waits at 1000ms (retry scheduled for 2000ms) but is then
// recorded successful at 1500ms — before its backoff elapsed.
func cliEarlySuccessLog() []byte {
	var raw []byte
	raw = append(raw, cliLogMagic...)
	raw = append(raw, cliFrame([]byte(`{"t":"version","v":1}`))...)
	raw = append(raw, cliFrame([]byte(`{"t":"source","chain":"a"}`))...)
	raw = append(raw, cliFrame([]byte(
		`{"t":"header","chain":"a","height":100,"root":"0x100","trusted":true}`))...)
	raw = append(raw, cliFrame([]byte(
		`{"t":"submit","seq":0,"id":"m0","from":"a","to":"b","nonce":1,"proofAt":10}`))...)
	raw = append(raw, cliFrame([]byte(
		`{"t":"result","now":500,"id":"m0","status":"success",`+
			`"reason":"delivered; proof verified by trusted header at height 100","attempts":1,`+
			`"consumeFrom":"a","consumeTo":"b","consumeNonce":1,"consumeBy":"m0"}`))...)
	raw = append(raw, cliFrame([]byte(
		`{"t":"submit","seq":1,"id":"w","from":"a","to":"b","nonce":7,"proofAt":10}`))...)
	raw = append(raw, cliFrame([]byte(
		`{"t":"result","now":1000,"id":"w","status":"waiting",`+
			`"reason":"waiting for trusted header covering height 10 (current 100)","attempts":1,"nextRetry":2000}`))...)
	raw = append(raw, cliFrame([]byte(
		`{"t":"result","now":1500,"id":"w","status":"success",`+
			`"reason":"delivered; proof verified by trusted header at height 100","attempts":2,`+
			`"consumeFrom":"a","consumeTo":"b","consumeNonce":7,"consumeBy":"w"}`))...)
	raw = append(raw, cliFrame([]byte(`{"t":"advance","now":1500}`))...)
	return raw
}

// A pre-retry success rejects the whole directory on open: exit code 12, no
// query output at all — the valid m0 record must not be partially served —
// the error names the scheduling violation, and a repeated open keeps failing
// without rewriting the log.
func TestCLIQueryEarlySuccessDuringBackoffCorruptExit12(t *testing.T) {
	state := t.TempDir()
	raw := cliEarlySuccessLog()
	writeCLIStateLog(t, state, raw)

	check := func(r cliResult) {
		t.Helper()
